function persist(){if(storageConflict){storeOK=false;return false}try{localStorage.setItem(STORAGE,JSON.stringify(db));storeOK=true;storeError=''}catch(e){storeOK=false;storeError=e.message}return storeOK}
function validateCoreImport(d){if(!d||d.schema!==VERSION)throw Error('Wymagany eksport Flux 11. Starsze wersje nie są migrowane automatycznie.');for(let k of ['users','spaces','boards','maps','nodes','edges','pages','fragments','messages','tasks','effects','anchors','attachments','proposals','prefs'])if(!d[k]||typeof d[k]!=='object'||Array.isArray(d[k]))throw Error('Nieprawidłowa sekcja: '+k);for(let coll of ['users','spaces','boards','maps','nodes','edges','pages','fragments','messages','tasks','effects','attachments','proposals'])for(let key of Object.keys(d[coll]))if(!/^[A-Za-z0-9_-]+$/.test(key)||['__proto__','constructor','prototype'].includes(key))throw Error('Niedozwolony identyfikator w '+coll);if(!d.users.u1||!d.users.ai)throw Error('Brakuje profili wymaganych w tej wersji demo.');for(let u of Object.values(d.users))if(typeof u.name!=='string')throw Error('Nieprawidłowy profil.');for(let [k,v] of Object.entries(d.spaces)){if(!/^[A-Za-z0-9_-]+$/.test(k)||v.id!==k||!Array.isArray(v.members)||v.members.some(u=>!d.users[u]))throw Error('Nieprawidłowi uczestnicy projektu.');}for(let collection of ['boards','maps','nodes','edges','pages','fragments','messages','tasks'])for(let [key,o]of Object.entries(d[collection])){if(!/^[A-Za-z0-9_-]+$/.test(key)||!o||o.id!==key||!d.spaces[o.space])throw Error('Nieprawidłowy obiekt: '+key)}for(let m of Object.values(d.messages)){if(!d.users[m.author]||typeof m.text!=='string'||m.files&&!Array.isArray(m.files)||!Number.isFinite(Date.parse(m.at)))throw Error('Nieprawidłowa wiadomość.');if(m.parent&&(!d.messages[m.parent]||d.messages[m.parent].parent||d.messages[m.parent].space!==m.space))throw Error('Nieprawidłowa odpowiedź.')}for(let n of Object.values(d.nodes))if(!d.maps[n.map]||d.maps[n.map].space!==n.space||!Number.isFinite(n.x)||!Number.isFinite(n.y))throw Error('Nieprawidłowa myśl.');for(let e of Object.values(d.edges))if(!d.nodes[e.a]||!d.nodes[e.b]||e.a===e.b||d.nodes[e.a].map!==e.map||d.nodes[e.b].map!==e.map)throw Error('Nieprawidłowe połączenie.');for(let t of Object.values(d.tasks))if(!d.boards[t.board]||d.boards[t.board].space!==t.space||!STATUSES[t.status]||!Array.isArray(t.nodeIds)||!Array.isArray(t.references))throw Error('Nieprawidłowe zadanie.');for(let p of Object.values(d.pages))if(typeof p.title!=='string'||typeof p.content!=='string'||!Array.isArray(p.history)||!Number.isFinite(p.version))throw Error('Nieprawidłowa strona wiki.');for(let f of Object.values(d.fragments))if(!d.pages[f.page]||d.pages[f.page].space!==f.space||typeof f.quote!=='string')throw Error('Nieprawidłowy fragment wiki.');for(let e of Object.values(d.effects))if(!d.messages[e.message]||!d.tasks[e.task]||d.messages[e.message].space!==d.tasks[e.task].space)throw Error('Nieprawidłowy skutek wiadomości.');for(let [ref,id] of Object.entries(d.anchors))if(!/^(task|node|page|fragment|map|edge):[A-Za-z0-9_-]+$/.test(ref)||!d.messages[id])throw Error('Nieprawidłowa rozmowa materiału.');for(let a of Object.values(d.attachments))if(typeof a.data!=='string'||!/^data:(image\/(png|jpeg|webp)|text\/(plain|markdown)|application\/pdf);base64,/i.test(a.data))throw Error('Niedozwolony załącznik.');for(let p of Object.values(d.prefs)){if(!['dark','light'].includes(p.theme))p.theme='dark';if(!['iris','amber','mint','sky','rose','teal','copper','lime','slate'].includes(p.accent))p.accent='iris';for(let k of ['plan','notes','read','drafts','reminders','notify'])if(!p[k]||typeof p[k]!=='object')p[k]={};}d.notifications=Array.isArray(d.notifications)?d.notifications:[];d.audit=Array.isArray(d.audit)?d.audit:[];return d}
function allowed(space){return !!db.spaces[space]?.members.includes(ui.user)}
function getObj(ref){let [type,id]=String(ref||'').split(':');let col={task:'tasks',node:'nodes',map:'maps',page:'pages',fragment:'fragments',message:'messages',edge:'edges',person:'users'}[type];return col?db[col][id]:null}
function refScope(ref){return getObj(ref)?.space||null}
function canRef(ref,space=ui.space){let [type,id]=String(ref||'').split(':');if(type==='person')return !!db.spaces[space]?.members.includes(id);let o=getObj(ref);return !!o&&o.space===space&&allowed(o.space)&&!o.archived}
function refsIn(text){return [...String(text||'').matchAll(/\[\[([a-z]+:[\w-]+)\]\]/g)].map(m=>m[1])}
function titleOf(ref){let [type,id]=String(ref||'').split(':'),o=getObj(ref);if(!o)return 'Materiał niedostępny';if(type==='person')return o.name;if(type==='fragment')return o.quote;if(type==='node'&&o.reference&&/^(task|page|fragment|map):/.test(o.reference))return titleOf(o.reference);if(type==='message')return String(o.text||'').replace(/\[\[([a-z]+):[\w-]+\]\]/g,(_,k)=>'['+(kindName[k]||'materiał')+']').slice(0,90)||(o.primary&&!o.primary.startsWith('message:')?titleOf(o.primary):'Wiadomość');if(type==='edge')return `${db.nodes[o.a]?.text||'Myśl'} ↔ ${db.nodes[o.b]?.text||'Myśl'}`;return o.title||o.text||'Bez tytułu'}
function plain(text){return String(text||'').replace(/\[\[([a-z]+:[\w-]+)\]\]/g,(_,r)=>titleOf(r))}
function descriptionOf(ref){let [type]=ref.split(':'),o=getObj(ref);if(!o)return '';if(type==='node')return db.maps[o.map]?.title||'';if(type==='task')return STATUSES[o.status]+' · '+(db.users[o.assignee]?.name||'Bez przypisania');if(type==='fragment')return (db.pages[o.page]?.title||'Wiki')+' · cytat v'+o.version;if(type==='page')return 'Wersja '+o.version;if(type==='message')return db.users[o.author]?.name+' · '+time(o.at);if(type==='edge')return db.maps[o.map]?.title||'';return ''}
function renderRef(ref,editor=false){if(!canRef(ref))return '<span class="ref-unavailable">Materiał niedostępny w tym gronie</span>';let type=ref.split(':')[0],label=titleOf(ref);if(label.length>58)label=label.slice(0,55)+'…';return `<span class="inline-ref" ${editor?'contenteditable="false"':''} data-ref="${esc(ref)}" role="link" tabindex="0" title="${esc(kindName[type]+': '+titleOf(ref))}">${I(kindIcon[type])}<span class="ref-kind">${kindName[type]}</span> ${esc(label)}</span>`}
function textHTML(text,editor=false){let parts=String(text||'').split(/(\[\[[a-z]+:[\w-]+\]\])/g);return parts.map(p=>/^\[\[/.test(p)?renderRef(p.slice(2,-2),editor):esc(p).replace(/\n/g,'<br>')).join('')}
function short(s,n=95){s=String(s||'');return s.length>n?s.slice(0,n-1)+'…':s}
function audit(action,details={}){db.audit.push({id:uid('ev'),action,actor:ui.user,space:ui.space,at:now(),...details});if(db.audit.length>500)db.audit.shift()}
function transact(label,fn,{map=false,renderUI=true}={}){let before=copy(db);try{if(!allowed(ui.space))throw Error('Nie masz dostępu do tego miejsca.');fn();db.revision++;audit(label);recordActivity(before,label);persist();if(renderUI)render();return true}catch(e){db=before;toast(e.message);return false}}
function activeBlockers(taskId){return Object.values(db.effects).filter(e=>e.kind==='blocker'&&e.task===taskId&&!e.resolvedAt)}
function resultMessage(taskId){let t=db.tasks[taskId];return t?.result?db.messages[t.result]:null}
function rootId(id){return db.messages[id]?.parent||id}
function replies(id){return Object.values(db.messages).filter(m=>m.parent===id).sort((a,b)=>a.at.localeCompare(b.at))}
function anchorFor(ref){return db.anchors[ref]||null}
function ensureAnchor(ref){let o=getObj(ref);if(!o||!canRef(ref))throw Error('Nie można otworzyć rozmowy o tym materiale.');if(db.anchors[ref]&&db.messages[db.anchors[ref]])return db.anchors[ref];let id=uid('m');db.messages[id]={id,space:o.space,author:ui.user,text:'',primary:ref,at:now(),version:1};db.anchors[ref]=id;if(ref.startsWith('task:'))db.tasks[o.id].anchor=id;return id}
function createMessage({space=ui.space,parent=null,text='',primary=null,author=ui.user,files=[]}){if(!db.spaces[space]?.members.includes(ui.user))throw Error('Brak dostępu.');if(parent&&(!db.messages[parent]||db.messages[parent].space!==space))throw Error('Wiadomość źródłowa nie jest dostępna.');for(let ref of refsIn(text))if(!canRef(ref,space))throw Error('Odnośnik nie jest dostępny dla odbiorców. Szkic został zachowany.');let id=uid('m'),m={id,space,parent:parent?rootId(parent):null,author,text:text.trim(),primary,at:now(),version:1,files};db.messages[id]=m;prefs().read[id]=true;
 const targets=new Set(refsIn(text).filter(r=>r.startsWith('person:')).map(r=>r.split(':')[1]));if(parent&&db.messages[rootId(parent)].author!=='ai')targets.add(db.messages[rootId(parent)].author);if(db.spaces[space].kind==='dm')db.spaces[space].members.forEach(u=>targets.add(u));for(let u of targets)if(u!==author&&db.spaces[space].members.includes(u)&&(refsIn(text).includes('person:'+u)||db.spaces[space].kind==='dm'?db.prefs[u]?.notify?.mentions!==false:db.prefs[u]?.notify?.replies!==false))db.notifications.push({id:uid('notif'),user:u,space,ref:'message:'+id,text:`${db.users[author]?.name||'Flux'}: ${short(plain(text),90)}`,read:false,at:now()});return m}
function createTask({title,source=null,nodeIds=[],references=[],board=ui.board,assignee=null,status='todo'}){title=String(title||'').trim();if(!title)throw Error('Wpisz, co chcesz zrobić.');if(!db.boards[board]||db.boards[board].space!==ui.space){board=Object.values(db.boards).find(b=>b.space===ui.space)?.id;if(!board){board=uid('b');db.boards[board]={id:board,space:ui.space,title:'Nasza praca'}}}let id=uid('t');let t={id,space:ui.space,board,title:title.slice(0,240),description:'',status,assignee,due:null,estimate:null,source,nodeIds:[...new Set(nodeIds)],references:[...new Set(references)],anchor:null,result:null,version:1,created:now()};db.tasks[id]=t;return t}
function markBlocker(messageId,taskId,helper=null){let t=db.tasks[taskId],m=db.messages[messageId];if(!t||!m||t.space!==m.space||t.space!==ui.space)throw Error('Wybierz zadanie z tej rozmowy.');if(t.status==='done')throw Error('Najpierw wznów ukończone zadanie.');if(Object.values(db.effects).some(e=>e.kind==='blocker'&&e.message===messageId&&e.task===taskId&&!e.resolvedAt))throw Error('Ta wiadomość już blokuje to zadanie.');let id=uid('eff');db.effects[id]={id,kind:'blocker',task:taskId,message:messageId,helper,createdAt:now(),createdBy:ui.user,resolvedAt:null};t.version++;if(helper&&helper!==ui.user)db.notifications.push({id:uid('notif'),user:helper,space:ui.space,ref:'task:'+taskId,text:`${db.users[ui.user].name} potrzebuje Twojej pomocy: ${t.title}`,at:now(),read:false});return id}
function solveBlocker(effectId,messageId){let e=db.effects[effectId],m=db.messages[messageId];if(!e||e.kind!=='blocker'||e.resolvedAt)throw Error('Ta przeszkoda jest już rozwiązana.');if(!m||m.space!==db.tasks[e.task].space||m.space!==ui.space)throw Error('Rozwiązanie musi być w tym samym projekcie.');if(e.message===messageId)throw Error('Wybierz odpowiedź rozwiązującą przeszkodę, nie samą przeszkodę.');e.resolvedAt=now();e.resolvedBy=ui.user;e.solution=messageId;db.tasks[e.task].version++;let id=uid('eff');db.effects[id]={id,kind:'solution',message:messageId,task:e.task,blocker:effectId,createdAt:now()};}
function setResult(taskId,messageId,finish=false){let t=db.tasks[taskId],m=db.messages[messageId];if(!t||!m||t.space!==m.space||m.space!==ui.space)throw Error('Wynik musi należeć do tego samego projektu.');if(finish&&activeBlockers(taskId).length)throw Error('Najpierw rozwiąż przeszkody. Możesz zapisać wynik bez kończenia zadania.');t.result=messageId;t.version++;if(finish){t.status='done';t.completedAt=now()}if(!Object.values(db.effects).some(e=>e.kind==='result'&&e.message===messageId&&e.task===taskId)){let id=uid('eff');db.effects[id]={id,kind:'result',message:messageId,task:taskId,createdAt:now()}}prepareWikiProposal(t,m);}
function setTaskStatus(id,status){let t=db.tasks[id];if(!t||t.space!==ui.space||!STATUSES[status])throw Error('Nieprawidłowe zadanie.');if(status==='done'&&activeBlockers(id).length)throw Error('Zadanie ma nierozwiązane przeszkody. Najpierw je odblokuj.');t.status=status;t.completedAt=status==='done'?now():null;t.version++}
function newNode(mapId,text,x=440,y=230,opts={}){let mp=db.maps[mapId];if(!mp||mp.space!==ui.space)throw Error('Nieprawidłowa mapa.');let id=uid('n');db.nodes[id]={id,space:ui.space,map:mapId,text:String(text||'Nowa myśl').slice(0,2000),x,y,...opts};mp.version++;if(opts.source){/* Only exact source message; never an entire multi-topic conversation. */Object.values(db.tasks).filter(t=>t.space===ui.space&&t.source===opts.source).forEach(t=>{if(!t.nodeIds.includes(id))t.nodeIds.push(id)})}return db.nodes[id]}
function connectNodes(a,b){let A=db.nodes[a],B=db.nodes[b];if(!A||!B||A.map!==B.map||A.space!==ui.space||a===b)throw Error('Połącz dwie różne myśli na tej samej mapie.');let existing=Object.values(db.edges).find(e=>(e.a===a&&e.b===b||e.a===b&&e.b===a));if(existing)return existing;let id=uid('edge');db.edges[id]={id,map:A.map,space:ui.space,a,b};db.maps[A.map].version++;return db.edges[id]}
function mapSnapshot(map=ui.map){return {nodes:copy(Object.values(db.nodes).filter(n=>n.map===map)),edges:copy(Object.values(db.edges).filter(e=>e.map===map))}}
function saveMapUndo(){let a=ui.mapUndo[ui.map]||(ui.mapUndo[ui.map]=[]);a.push(mapSnapshot());if(a.length>30)a.shift();ui.mapRedo[ui.map]=[]}
function applyMapSnapshot(snap){let map=ui.map;for(let [id,n]of Object.entries(db.nodes))if(n.map===map)delete db.nodes[id];for(let [id,e]of Object.entries(db.edges))if(e.map===map)delete db.edges[id];snap.nodes.forEach(n=>db.nodes[n.id]=n);snap.edges.forEach(e=>db.edges[e.id]=e);db.maps[map].version++;ui.selected=ui.selected.filter(id=>db.nodes[id]);ui.edge=null;}
function refsForTask(t){return [...t.nodeIds.filter(id=>db.nodes[id]&&!db.nodes[id].archived).map(id=>'node:'+id),...t.references.filter(r=>canRef(r,t.space))]}
function tasksForNode(id){return Object.values(db.tasks).filter(t=>t.space===ui.space&&t.nodeIds.includes(id))}
function neighbors(id){return Object.values(db.edges).filter(e=>e.a===id||e.b===id).map(e=>db.nodes[e.a===id?e.b:e.a]).filter(n=>n&&!n.archived)}
function relatedTasksToMessage(id){return Object.values(db.tasks).filter(t=>t.space===ui.space&&(t.source===id||anchorFor('task:'+t.id)===rootId(id)||Object.values(db.effects).some(e=>e.task===t.id&&e.message===id)))}
function sourcesForMessage(id){return [...Object.values(db.nodes).filter(n=>n.source===id&&!n.archived).map(n=>'node:'+n.id),...Object.values(db.tasks).filter(t=>t.source===id).map(t=>'task:'+t.id)]}
function usageOf(ref){let res=[];for(let m of Object.values(db.messages))if(m.space===ui.space&&refsIn(m.text).includes(ref))res.push({ref:'message:'+m.id,reason:'Wspomniano w wiadomości'});for(let p of Object.values(db.pages))if(p.space===ui.space&&refsIn(p.content).includes(ref))res.push({ref:'page:'+p.id,reason:'W treści wiki'});for(let t of Object.values(db.tasks))if(t.space===ui.space&&(t.references.includes(ref)||refsIn(t.description).includes(ref)))res.push({ref:'task:'+t.id,reason:'Źródło dla zadania'});for(let n of Object.values(db.nodes))if(n.space===ui.space&&!n.archived&&n.reference===ref)res.push({ref:'node:'+n.id,reason:'Odniesienie na mapie'});return res}
function coreApplyProposal(id){let p=db.proposals[id];if(!p||p.status!=='pending')throw Error('Ta propozycja nie czeka już na zastosowanie.');if(p.space!==ui.space)throw Error('Inny projekt.');if(p.kind==='wiki'){let page=db.pages[p.page],m=db.messages[p.source];if(!page||page.version!==p.pageVersion||m?.version!==p.sourceVersion||db.tasks[p.task]?.result!==p.source)throw Error('Źródło lub wiki zmieniły się. Ta propozycja jest nieaktualna.');savePage(page.id,page.title,page.content+p.addition);p.appliedVersion=page.version;}if(p.kind==='layout'){if(db.maps[p.map]?.version!==p.mapVersion)throw Error('Mapa zmieniła się od przygotowania układu. Przygotuj nową propozycję.');ui.map=p.map;saveMapUndo();for(let pos of p.positions)Object.assign(db.nodes[pos.id],{x:pos.x,y:pos.y});db.maps[p.map].version++;}if(p.kind==='task'){let t=createTask({title:p.title,source:p.source});p.createdTask=t.id}p.status='applied';p.appliedAt=now();}
function savePage(id,title,content){let p=db.pages[id];if(!p||p.space!==ui.space)throw Error('Strona niedostępna.');if(!title.trim())throw Error('Wpisz tytuł strony.');for(let r of refsIn(content))if(!canRef(r))throw Error('Wiki zawiera odnośnik niedostępny w tym projekcie.');p.history.push({version:p.version,title:p.title,content:p.content,at:now(),author:ui.user});p.title=title.trim();p.content=content;p.version++;}
/* ---------- projections ---------- */
function material(ref,reason='',compact=false){if(!canRef(ref))return '<div class="notice">Ten materiał nie jest dostępny w tym miejscu.</div>';let type=ref.split(':')[0],o=getObj(ref),extra='';if(type==='task'){let blocks=activeBlockers(o.id);extra=`<div class="meta"><span class="pill ${o.status==='doing'?'accent':o.status==='done'?'good':''}">${STATUSES[o.status]}</span>${blocks.length?'<span class="pill warn">'+I('block')+'Czeka na pomoc</span>':''}${o.due?'<span class="pill">'+I('calendar')+dateLabel(o.due)+'</span>':''}</div>`}if(type==='fragment')extra=`<div class="excerpt">${esc(db.pages[o.page]?.title||'Wiki')} · cytat z wersji ${o.version}</div>`;if(type==='node')extra=`<div class="excerpt">${esc(db.maps[o.map]?.title||'Mapa')}</div>`;return `<button class="material" data-action="open-ref" data-ref="${esc(ref)}"><div class="kindline">${I(kindIcon[type])}${kindName[type]}${reason?' <span style="margin-left:auto;text-transform:none;letter-spacing:0;font-weight:400">'+esc(reason)+'</span>':''}</div><div class="title">${esc(short(titleOf(ref),compact?85:140))}</div>${extra}${type==='message'?`<div class="caption">${esc(descriptionOf(ref))}</div>`:''}</button>`}
function badgeForMessage(m){let effects=Object.values(db.effects).filter(e=>e.message===m.id),arr=[];for(let e of effects){let t=db.tasks[e.task];if(e.kind==='blocker')arr.push(`<div class="msg-effect ${e.resolvedAt?'good':''}">${I(e.resolvedAt?'check':'block')}<button data-action="open-ref" data-ref="task:${e.task}">${e.cancelledAt?'Wycofana przeszkoda':e.resolvedAt?'Przeszkoda rozwiązana':'Blokuje'} · ${esc(short(t?.title||'Zadanie',48))}</button></div>`);if(e.kind==='solution'&&!e.cancelledAt)arr.push(`<div class="msg-effect good">${I('check')}<button data-action="open-ref" data-ref="task:${e.task}">Rozwiązanie · ${esc(short(t?.title||'Zadanie',48))}</button></div>`);if(e.kind==='result'&&!e.cancelledAt)arr.push(`<div class="msg-effect good">${I('flag')}<button data-action="open-ref" data-ref="task:${e.task}">${t?.result===m.id?'Aktualny wynik':'Poprzedni wynik'} · ${esc(short(t?.title||'Zadanie',48))}</button></div>`)}if(m.parent&&db.messages[m.parent]?.solution===m.id)arr.push(`<div class="msg-effect good">${I('check')}Rozwiązanie pytania</div>`);return arr.join('')}
function coreProposalHTML(id){let p=db.proposals[id];if(!p)return '';let active=p.status==='pending',target=p.kind==='wiki'?'page:'+p.page:p.kind==='layout'?'map:'+p.map:null;return `<div class="proposal"><div class="label">${I('spark')} ${p.status==='applied'?'Zmiana zastosowana':p.status==='dismissed'?'Propozycja odrzucona':'Propozycja · bez zmian w projekcie'}</div><p>${p.kind==='wiki'?'Dopisanie obserwacji do '+renderRef(target):p.kind==='layout'?`Nowy układ ${p.positions.length} myśli. `+renderRef(target):esc(p.title)}</p>${p.kind==='wiki'?`<div class="hint">${esc(short(plain(db.messages[p.source]?.text),150))}</div>`:''}${active?`<div class="proposal-actions">${B(I('check')+' Zastosuj','proposal-apply',`data-id="${p.id}"`,'small primary')}${B('Odrzuć','proposal-dismiss',`data-id="${p.id}"`,'small quiet')}</div>`:p.createdTask?renderRef('task:'+p.createdTask):''}</div>`}
function coreMessageHTML(m,inDrawer=false){let effects=Object.values(db.effects).filter(e=>e.message===m.id);let kind=effects.some(e=>e.kind==='blocker'&&!e.resolvedAt)?'blocker':effects.some(e=>e.kind==='solution')||db.messages[m.parent]?.solution===m.id?'solution':effects.some(e=>e.kind==='result')?'result':'';let children=replies(m.id),products=sourcesForMessage(m.id);let unread=children.filter(c=>!prefs().read[c.id]).length;return `<article class="msg ${m.author===ui.user?'self':''} ${m.author==='ai'?'ai':''} ${kind?'marked-'+kind:''} ${ui.flash===m.id?'highlight':''}" data-message="${m.id}"><span class="msg-avatar">${avatar(m.author)}</span><div class="msg-wrap"><div class="msg-meta"><b>${esc(db.users[m.author]?.name||'Nieznany')}</b>${m.author==='ai'?'<span class="pill accent" style="font-size:8px;padding:0 4px">DEMO</span>':''}<span>${time(m.at)}</span>${m.editedAt?'<span>edytowano</span>':''}</div><div class="bubble">${badgeForMessage(m)}${m.text?`<div class="msg-text">${textHTML(m.text)}</div>`:''}${m.primary?material(m.primary):''}${(m.files||[]).map(id=>{let a=db.attachments[id];return a?`<button class="attachment" data-action="attachment-open" data-id="${id}">${a.type.startsWith('image/')?`<img src="${a.data}" alt="${esc(a.name)}">`:I('file')+' '+esc(a.name)}</button>`:''}).join('')}${m.proposal?proposalHTML(m.proposal):''}${products.length?`<div class="msg-links">${products.map(r=>`<button class="link-mini" data-action="open-ref" data-ref="${r}">${I(kindIcon[r.split(':')[0]])}${r.startsWith('node:')?'Na mapie':'Podjęte zadanie'}: ${esc(short(titleOf(r),38))}${I('arrow')}</button>`).join('')}</div>`:''}${m.solution?`<button class="replies-line" data-action="comments" data-id="${m.id}">${I('check')} To pytanie ma rozwiązanie</button>`:''}</div><div class="msg-actions">${m.author!=='ai'?`<button data-action="react" data-id="${m.id}" title="Lubię to">${I('heart')}${m.reactions?.length?m.reactions.length:''}</button>`:''}${!m.parent?`<button data-action="comments" data-id="${m.id}">${I('reply')}${children.length?children.length+' '+plural(children.length,'odpowiedź','odpowiedzi','odpowiedzi'):'Odpowiedz'}${unread?'<span class="unread-dot"></span>':''}</button>`:''}${!inDrawer&&m.author!=='ai'?`<button class="hide-in-drawer" data-action="message-map" data-id="${m.id}" title="Rozwiń tę myśl na mapie">${I('map')} Na mapę</button>`:''}${m.author!=='ai'?`<button data-action="message-menu" data-id="${m.id}" aria-label="Opcje wiadomości" title="Opcje wiadomości">${I('more')}</button>`:''}</div></div></article>`}
function unreadCount(space){return Object.values(db.messages).filter(m=>m.space===space&&m.author!==ui.user&&!prefs().read[m.id]).length}
function renderSidebar10(){let projects=Object.values(db.spaces).filter(s=>s.kind==='project'&&allowed(s.id)),dms=Object.values(db.spaces).filter(s=>s.kind==='dm'&&allowed(s.id)),unread=db.notifications.filter(n=>n.user===ui.user&&!n.read&&allowed(n.space)).length;return `<aside class="sidebar"><button class="brand" data-action="navigate-home">${logo()}flux <span class="version">STUDIO / 11</span></button><button class="search-launch" data-action="search">${I('search')} Znajdź we Fluxie <kbd>Ctrl K</kbd></button><button class="nav ${ui.view==='home'?'active':''}" data-action="navigate-home">${I('home')}<span class="grow">U mnie</span>${unread?`<span class="badge-number">${unread}</span>`:''}</button>${allowed('private1')?`<button class="nav ${ui.space==='private1'&&ui.view!=='home'?'active':''}" data-action="space" data-id="private1">${I('edit')}<span class="grow">Mój szkicownik</span>${I('lock')}</button>`:''}<div class="side-scroll"><div class="side-label"><span class="eyebrow">Projekty</span>${IB('plus','Nowy projekt','new-project')}</div>${projects.map(s=>`<button class="nav ${ui.space===s.id&&ui.view!=='home'?'active':''}" data-action="space" data-id="${s.id}"><span class="nav-icon">${I(s.icon||'spark')}</span><span class="grow">${esc(s.name)}<span class="sub">${s.members.length} ${plural(s.members.length,'osoba','osoby','osób')}</span></span>${unreadCount(s.id)?'<span class="unread-dot"></span>':''}</button>`).join('')}<div class="side-label"><span class="eyebrow">Wiadomości</span>${IB('plus','Napisz prywatnie','new-dm')}</div>${dms.map(s=>{let who=s.members.find(u=>u!==ui.user)||ui.user;return `<button class="nav ${ui.space===s.id&&ui.view!=='home'?'active':''}" data-action="space" data-id="${s.id}">${avatar(who)}<span class="grow">${esc(db.users[who].name)}</span>${unreadCount(s.id)?'<span class="unread-dot"></span>':''}</button>`}).join('')}</div><div class="side-bottom"><div class="demo-tag"><span class="status-dot" style="${storeOK?'':'background:var(--amber)'}"></span><span>${storeOK?'Zapis lokalny · prototyp':'Brak zapisu · eksportuj dane'}</span>${IB('help','O tej wersji','about')}</div><div class="row" style="padding:8px">${avatar(ui.user)}<div class="grow"><div style="font-size:12px">${esc(db.users[ui.user].name)}</div><div class="dim" style="font-size:10px">Twoja przestrzeń pracy</div></div>${IB('settings','Ustawienia i wygląd','settings')}</div></div></aside>`}
function renderHeader10(){let s=db.spaces[ui.space];if(ui.view==='home')return `<header class="header" style="min-height:75px;padding-top:20px"><div class="head-top">${IB('menu','Otwórz nawigację','toggle-sidebar','','mobile-only')}<div class="grow"><div class="head-name">U mnie</div><div class="head-sub">Tylko Twoje projekty, wiadomości i następne kroki.</div></div>${B(I('download')+' Eksport','export','','small quiet')}${IB('sun','Zmień jasny / ciemny','toggle-theme')}</div></header>`;return `<header class="header"><div class="head-top">${IB('menu','Otwórz nawigację','toggle-sidebar','','mobile-only')}<span class="project-symbol">${I(s.icon||'spark')}</span><div class="grow"><div class="head-name">${esc(s.kind==='dm'?db.users[s.members.find(u=>u!==ui.user)]?.name:s.name)}</div><div class="head-sub">${I('lock')}${s.kind==='private'?'Tylko Ty':s.members.map(id=>id===ui.user?'Ty':db.users[id].name).join(' · ')}</div></div><div class="avatars">${s.members.map(id=>avatar(id,true)).join('')}</div>${s.kind!=='private'?B(I('headphones')+'<span class="live-label"> Zróbmy to razem</span>','live','','live-button quiet'):''}${B(I('robot')+'<span class="ai-header-label"> AI</span>','agent-panel','','small quiet')}${IB('settings','Ustawienia tego projektu','project-settings')}${IB('sun','Zmień jasny / ciemny','toggle-theme')}</div><nav class="tabs" aria-label="Widoki projektu">${[['chat','chat','Rozmowa'],['map','map','Mapa'],['tasks','task','Zadania'],['wiki','wiki','Wiki']].map(([view,icon,name])=>`<button class="tab ${ui.view===view?'active':''}" data-action="view" data-view="${view}" ${ui.view===view?'aria-current="page"':''}>${I(icon)}${name}</button>`).join('')}</nav></header>`}
function contextKey(){if(ui.drawer?.kind==='comments')return 'reply:'+ui.drawer.id;if(ui.drawer?.kind==='object'&&ui.drawerTab==='talk')return 'entity:'+ui.drawer.ref;return 'chat:'+ui.space}
function composer(key,taskId=null){let mode=taskId?ui.composerMode:'normal',draft=prefs().drafts[key]||'',members=db.spaces[ui.space].members;return `<div class="composer-wrap"><div class="composer" data-composer="${esc(key)}">${ui.pendingShares?.[key]?`<div class="row between" style="margin-bottom:8px"><span class="hint">Pokażesz ten materiał w rozmowie</span>${IB('x','Anuluj udostępnienie','cancel-share',`data-key="${esc(key)}"`)}</div>${material(ui.pendingShares[key])}<div style="height:9px"></div>`:''}${taskId?`<div class="composer-mode" aria-label="Skutek wiadomości">${[['normal','chat','Wiadomość'],['blocker','block','Przeszkoda'],['result','flag','Wynik']].map(([v,i,l])=>`<button data-action="compose-mode" data-mode="${v}" class="${mode===v?'active':''}">${I(i)}${l}</button>`).join('')}</div>${mode==='blocker'?`<div class="mode-context">Zablokuje to zadanie. Wykonawca pozostaje bez zmian.</div><select data-preserve="helper" id="composer-helper" style="font-size:11px;padding:6px;margin-bottom:9px"><option value="">Pomocnik — opcjonalnie</option>${members.filter(id=>id!==ui.user).map(id=>`<option value="${id}">${esc(db.users[id].name)}</option>`).join('')}</select>`:mode==='result'?`<div class="mode-context">Wynik będzie widoczny przy zadaniu i powiązanych myślach.</div><label class="checkbox" style="font-size:11px"><input type="checkbox" id="composer-finish" data-preserve="finish"> Zakończ też zadanie</label>`:''}`:''}<div class="editor" role="textbox" aria-label="${key.startsWith('chat:')?'Napisz wiadomość':'Napisz odpowiedź'}" aria-multiline="true" contenteditable="true" spellcheck="true" data-key="${esc(key)}" data-placeholder="${mode==='blocker'?'Co uniemożliwia Ci dalszą pracę?':mode==='result'?'Co powstało albo czego się dowiedzieliście?':key.startsWith('chat:')?'Napisz wiadomość…':'Napisz odpowiedź…'}">${textHTML(draft,true)}</div>${(ui.attachments[key]||[]).length?`<div class="pending-files">${ui.attachments[key].map(id=>`<span class="pill">${I('file')}${esc(db.attachments[id]?.name)}<button data-action="remove-attachment" data-id="${id}" data-key="${esc(key)}" aria-label="Usuń załącznik">×</button></span>`).join('')}</div>`:''}<div class="composer-tools">${IB('paperclip','Dodaj załącznik','attach',`data-key="${esc(key)}"`)}<button class="iconbtn" data-action="mention-open" data-key="${esc(key)}" aria-label="Wskaż osobę lub materiał" title="Osoba lub materiał @" style="font-size:17px">@</button>${B(I('robot')+' AI','ai-prompt',`data-key="${esc(key)}"`,'small quiet')}<span class="grow"></span><button class="send" data-action="send" data-key="${esc(key)}" ${taskId?`data-task="${taskId}"`:''} aria-label="Wyślij wiadomość" title="Wyślij · Enter">${I('send')}</button></div></div><div class="composer-caption"><span>${I('lock')}${members.map(id=>id===ui.user?'Ty':db.users[id].name).join(', ')}</span><span class="kbd-hint">Enter wyślij · Shift Enter nowa linia</span></div></div>`}
function renderChat(){let messages=Object.values(db.messages).filter(m=>m.space===ui.space&&!m.parent).sort((a,b)=>a.at.localeCompare(b.at));let s=db.spaces[ui.space];let sharedTaskDrawer=ui.drawer?.kind==='object'&&ui.drawerTab==='talk';return `<section class="chat">${renderReturnStrip()}<div class="messages" id="chat-scroll"><div class="day-divider">${s.kind==='dm'?'Wasza prywatna rozmowa':s.kind==='private'?'Twoje myśli, bez odbiorców':'Pomysły zaczynają się od rozmowy'}</div>${messages.length?messages.map((m,i)=>(i===0||m.at.slice(0,10)!==messages[i-1].at.slice(0,10)?`<div class="day-divider">${new Date(m.at).toLocaleDateString('pl-PL',{weekday:'long',day:'numeric',month:'long'})}</div>`:'')+messageHTML(m)).join(''):`<div class="empty">${I('chat')}<h3>Od czego zaczynamy?</h3><p>Napisz myśl. Nie potrzebujesz tematu ani gotowego planu.</p></div>`}</div>${sharedTaskDrawer?`<div class="composer-wrap"><div class="notice row">${I('reply')}<span class="grow">Piszesz teraz przy otwartym materiale.</span>${B('Wróć do rozmowy','close-drawer','','small quiet')}</div></div>`:composer('chat:'+ui.space)}</section>`}
function messageContext(m){let taskRefs=relatedTasksToMessage(m.id).map(t=>'task:'+t.id);let root=db.messages[rootId(m.id)];if(root?.primary?.startsWith('task:')&&!taskRefs.includes(root.primary))taskRefs.push(root.primary);let products=sourcesForMessage(m.id),explicit=refsIn(m.text).filter(r=>!r.startsWith('person:')&&canRef(r));let all=[...new Set([...taskRefs,...products,...explicit,...(root?.primary?[root.primary]:[])])];return all}
function objectTop(ref){let type=ref.split(':')[0],o=getObj(ref);if(type==='task')return taskTop(o);if(type==='node')return `<div class="eyebrow" style="margin-bottom:9px">Myśl · ${esc(db.maps[o.map].title)}</div><h2>${esc(o.text)}</h2>${o.reference?`<div class="linked-group"><h4>Wskazany materiał</h4>${material(o.reference)}</div>`:''}<div class="row wrap" style="margin:14px 0">${B(I('map')+' Pokaż na mapie','locate-node',`data-id="${o.id}"`,'small')}${B(I('send')+' Do rozmowy','share',`data-ref="node:${o.id}"`,'small quiet')}</div>${o.source?`<button class="backlink" data-action="jump-message" data-id="${o.source}">${I('reply')} Z wypowiedzi ${esc(db.users[db.messages[o.source]?.author]?.name||'')}</button>`:''}${tasksForNode(o.id).length?`<div class="linked-group"><h4>Sprawdzamy ten pomysł</h4>${tasksForNode(o.id).map(t=>material('task:'+t.id)).join('')}${tasksForNode(o.id).map(t=>resultMessage(t.id)?`<div class="task-result"><span class="eyebrow" style="color:var(--green)">${I('flag')} Aktualny wynik</span><p>${textHTML(short(resultMessage(t.id).text,230))}</p><button class="backlink" data-action="jump-message" data-id="${t.result}">Wypowiedź źródłowa ${I('arrow')}</button></div>`:'').join('')}</div>`:''}<div class="row">${B(I('plus')+' Podejmij zadanie','new-task',`data-nodes="${o.id}"`,'small soft')}</div>${neighbors(o.id).length?`<div class="linked-group"><h4>Połączone na mapie · nie wspólne komentarze</h4><div class="ctx-neighbors">${neighbors(o.id).map(n=>`<button data-action="open-ref" data-ref="node:${n.id}">${I('map')} ${esc(short(n.text,36))}</button>`).join('')}</div></div>`:''}`;
 if(type==='edge')return `<div class="eyebrow">Rozmowa o połączeniu</div><h2 style="margin-top:12px">${esc(db.nodes[o.a]?.text)} <span class="muted">↔</span> ${esc(db.nodes[o.b]?.text)}</h2><div class="map-mini"><span>${esc(short(db.nodes[o.a]?.text,25))}</span><span>${esc(short(db.nodes[o.b]?.text,25))}</span></div><div class="context-intro">Ta rozmowa dotyczy relacji. Nie scala rozmów obu myśli i nie tworzy zależności między zadaniami.</div><div class="row wrap">${B('Pierwsza myśl','open-ref',`data-ref="node:${o.a}"`,'small')}${B('Druga myśl','open-ref',`data-ref="node:${o.b}"`,'small')}</div>`;
 if(type==='fragment'){let p=db.pages[o.page],match=fragmentStatus(o);return `<div class="eyebrow">Wiki · konkretny fragment</div><h2 style="margin-top:10px">${esc(p?.title||'Usunięta strona')}</h2><div class="quote-preview">${esc(o.quote)}</div><p class="hint">Cytat z wersji ${o.version}. ${match.ok?'Odnaleziony w aktualnej treści.':'Źródło się zmieniło lub cytat nie jest jednoznaczny. Zachowano pierwotny tekst.'}</p><div class="row wrap" style="margin:16px 0">${B(I('wiki')+' Pokaż fragment','locate-fragment',`data-id="${o.id}"`,'small')}${B(I('send')+' Do rozmowy','share',`data-ref="fragment:${o.id}"`,'small quiet')}</div><div class="row wrap">${B(I('map')+' Na mapę','ref-map',`data-ref="fragment:${o.id}"`,'small')}${B(I('task')+' Do zadania','ref-task',`data-ref="fragment:${o.id}"`,'small')}</div>`;}
 if(type==='page')return `<div class="eyebrow">Wiki · wersja ${o.version}</div><h2 style="margin-top:10px">${esc(o.title)}</h2><div class="drawer-summary">${esc(short(o.content.replace(/[#`\[\]]/g,''),300))}</div><div class="row wrap">${B(I('wiki')+' Otwórz stronę','locate-page',`data-id="${o.id}"`,'small')}${B(I('send')+' Do rozmowy','share',`data-ref="page:${o.id}"`,'small quiet')}</div>`;
 if(type==='map')return `<div class="eyebrow">Mapa · ${Object.values(db.nodes).filter(n=>n.map===o.id&&!n.archived).length} myśli</div><h2 style="margin-top:10px">${esc(o.title)}</h2><div style="margin:16px 0">${B(I('map')+' Otwórz mapę','locate-map',`data-id="${o.id}"`,'small')}${B(I('send')+' Do rozmowy','share',`data-ref="map:${o.id}"`,'small quiet')}</div>`;return ''}
function taskTop(t){let blockers=activeBlockers(t.id),result=resultMessage(t.id),p=prefs();return `<div class="row between"><span class="eyebrow">Zadanie · ${esc(db.boards[t.board]?.title)}</span>${IB('more','Opcje zadania','task-menu',`data-id="${t.id}"`)}</div><h2 style="margin-top:12px">${esc(t.title)}</h2><div class="row wrap" style="margin-top:12px"><select data-change="task-status" data-id="${t.id}" aria-label="Stan zadania" style="width:auto;font-size:11px;padding:6px 10px">${Object.entries(STATUSES).map(([v,n])=>`<option value="${v}" ${t.status===v?'selected':''}>${n}</option>`).join('')}</select>${blockers.length?`<span class="pill warn">${I('block')} ${blockers.length} ${plural(blockers.length,'przeszkoda','przeszkody','przeszkód')}</span>`:''}${B(p.plan[t.id]===day()?I('check')+' W moim planie':I('sun')+' Na dziś','plan-today',`data-id="${t.id}"`,'small '+(p.plan[t.id]===day()?'soft':'quiet'))}</div>${t.description?`<div class="context-intro">${textHTML(t.description)}</div>`:`<button class="backlink" data-action="task-edit" data-id="${t.id}">${I('edit')} Dodaj opis, gdy będzie potrzebny</button>`}<div class="detail-fields"><button class="detail-field" data-action="task-assignee" data-id="${t.id}"><div class="label">${I('user')} Wykonawca</div><div class="value">${esc(db.users[t.assignee]?.name||'Nikt jeszcze')}</div></button><button class="detail-field" data-action="task-due" data-id="${t.id}"><div class="label">${I('calendar')} Termin ukończenia</div><div class="value">${dateLabel(t.due)}</div></button><button class="detail-field" data-action="task-estimate" data-id="${t.id}"><div class="label">${I('clock')} Orientacyjny nakład</div><div class="value">${t.estimate?'Około '+esc(effortLabel(t)):'Nie szacowano'}</div></button><button class="detail-field" data-action="task-plan" data-id="${t.id}"><div class="label">${I('sun')} Mój plan · tylko dla mnie</div><div class="value">${p.plan[t.id]?dateLabel(p.plan[t.id]):'Nie zaplanowano'}</div></button></div>${blockers.map(e=>`<section class="task-block"><div class="row between"><span class="eyebrow" style="color:var(--amber)">${I('block')} Czeka${e.helper?' na '+esc(db.users[e.helper]?.name):' na rozwiązanie'}</span>${IB('external','Otwórz źródłową wypowiedź','jump-message',`data-id="${e.message}"`)}</div><p>${textHTML(short(db.messages[e.message]?.text,250))}</p>${B(I('check')+' Mam rozwiązanie','resolve',`data-id="${e.id}"`,'small')}</section>`).join('')}${result?`<section class="task-result"><span class="eyebrow" style="color:var(--green)">${I('flag')} Aktualny wynik · jedna wypowiedź</span><p>${textHTML(short(result.text,300))}</p><button class="backlink" data-action="jump-message" data-id="${result.id}">Wróć do wypowiedzi ${I('arrow')}</button></section>`:''}<button class="resume-note" data-action="resume-edit" data-id="${t.id}" style="width:100%;text-align:left"><div class="row" style="font-size:10px;margin-bottom:5px">${I('lock')} Mój punkt powrotu</div>${esc(p.notes[t.id]||'Zostaw sobie jedno zdanie na następny raz…')}</button>${t.source?`<button class="backlink" data-action="jump-message" data-id="${t.source}">${I('reply')} Rozmowa, z której powstało zadanie</button>`:''}${t.completedAt?`<p class="hint" style="margin-top:10px">Zakończono ${new Date(t.completedAt).toLocaleString('pl-PL')}</p>`:''}`}
function objectContext(ref){let type=ref.split(':')[0],o=getObj(ref),html='';if(type==='task'){if(o.nodeIds.length)html+=`<div class="linked-group"><h4>Praca nad tym pomysłem</h4>${o.nodeIds.filter(id=>db.nodes[id]&&!db.nodes[id].archived).map(id=>material('node:'+id)).join('')}</div>`;if(o.references.length)html+=`<div class="linked-group"><h4>Materiały potrzebne do pracy</h4>${o.references.map(r=>material(r)).join('')}</div>`;html+=`<div class="row wrap">${B(I('link')+' Powiąż materiał','link-task',`data-id="${o.id}"`,'small')}${B(I('map')+' Rozrysuj problem','sketch-task',`data-id="${o.id}"`,'small')}</div>`}let uses=usageOf(ref);if(uses.length)html+=`<div class="linked-group"><h4>Wspomniano lub wykorzystano w</h4>${uses.map(u=>`<button class="backlink" data-action="open-ref" data-ref="${u.ref}">${I(kindIcon[u.ref.split(':')[0]])}<span>${esc(short(titleOf(u.ref),55))}<br><small class="dim">${esc(u.reason)}</small></span></button>`).join('')}</div>`;return html||'<p class="hint" style="margin:16px 0">Dalsze powiązania pojawią się tutaj, gdy odwołasz się do tego materiału lub wykorzystasz go w pracy.</p>'}
function renderCoreDrawer(){if(!ui.drawer)return '';let d=ui.drawer;if(d.kind==='comments'){let root=db.messages[d.id];if(!root)return '';let children=replies(root.id),context=messageContext(root);return `<aside class="drawer" aria-label="Odpowiedzi przy wiadomości"><div class="drawer-head"><span class="eyebrow">${I('reply')} Odpowiedzi · ${children.length}</span>${IB('external','Znajdź wiadomość w rozmowie','jump-message',`data-id="${root.id}"`)}${IB('x','Zamknij panel','close-drawer')}</div><div class="drawer-body" id="drawer-scroll">${messageHTML(root,true)}${context.length?`<details class="linked-group"><summary class="hint" style="cursor:pointer">Z tą wiadomością wiąże się ${context.length} ${plural(context.length,'materiał','materiały','materiałów')}</summary><div class="stack" style="margin-top:10px">${context.map(r=>material(r)).join('')}</div></details>`:''}<div class="divider"></div>${children.length?children.map(m=>messageHTML(m,true)).join(''):'<p class="hint">Odpowiedz na tę konkretną myśl. Bez zakładania tematu.</p>'}</div><div class="drawer-footer">${composer('reply:'+root.id)}</div></aside>`}if(d.kind==='object'){let ref=d.ref,o=getObj(ref);if(!o||!canRef(ref))return '';let type=ref.split(':')[0],anchor=anchorFor(ref),children=anchor?replies(anchor):[],root=anchor?db.messages[anchor]:null;return `<aside class="drawer" aria-label="Panel materiału"><div class="drawer-head">${I(kindIcon[type])}<span class="eyebrow">${kindName[type]}</span>${IB('copy','Kopiuj odnośnik','copy-ref',`data-ref="${ref}"`)}${IB('x','Zamknij panel','close-drawer')}</div><div class="drawer-body" id="drawer-scroll">${objectTop(ref)}<div class="drawer-tabs"><button data-action="drawer-tab" data-tab="talk" class="${ui.drawerTab==='talk'?'active':''}">Rozmowa${children.length?' · '+children.length:''}</button><button data-action="drawer-tab" data-tab="context" class="${ui.drawerTab==='context'?'active':''}">Powiązania</button></div>${ui.drawerTab==='context'?objectContext(ref):`<div class="hint" style="margin-bottom:15px">${anchor?'Te same odpowiedzi są dostępne pod kartą w rozmowie projektu.':'Pierwsza odpowiedź pokaże materiał w rozmowie projektu. Samo otwarcie panelu niczego nie publikuje.'}</div>${root?.text?messageHTML(root,true):''}${children.map(m=>messageHTML(m,true)).join('')}${!children.length&&!root?.text?'<div class="empty" style="padding:14px 0">Jeszcze bez komentarzy.</div>':''}`}</div>${ui.drawerTab==='talk'?`<div class="drawer-footer">${composer('entity:'+ref,type==='task'?o.id:null)}</div>`:''}</aside>`}return ''}
function taskCard10(t){let blockers=activeBlockers(t.id),node=t.nodeIds.map(id=>db.nodes[id]).find(Boolean);return `<article class="task-card" draggable="true" data-task="${t.id}" data-action="open-ref" data-ref="task:${t.id}" tabindex="0"><span class="task-number">FX-${Object.keys(db.tasks).indexOf(t.id)+1}</span><h3>${esc(t.title)}</h3><div class="meta">${t.assignee?avatar(t.assignee,true):'<span class="avatar tiny">'+I('user')+'</span>'}${t.due?`<span class="pill ${t.due<day()&&t.status!=='done'?'warn':''}">${I('calendar')}${dateLabel(t.due)}</span>`:''}${t.estimate?`<span class="pill">${I('clock')}${t.estimate<60?effortLabel(t):t.estimate/60+' h'}</span>`:''}${blockers.length?`<span class="pill warn">${I('block')}Czeka</span>`:''}${prefs().plan[t.id]===day()?'<span class="pill accent">Mój plan</span>':''}</div>${node||t.source?`<div class="links">${I(node?'map':'chat')} ${esc(short(node?.text||'Z rozmowy',37))}</div>`:''}</article>`}
function renderTasks10(){let boards=Object.values(db.boards).filter(b=>b.space===ui.space);if(ui.board!=='all'&&!boards.some(b=>b.id===ui.board))ui.board=boards[0]?.id||'all';let ts=Object.values(db.tasks).filter(t=>t.space===ui.space&&(ui.board==='all'||t.board===ui.board)&&(ui.filterTasks!=='mine'||t.assignee===ui.user));return `<div class="toolbar"><select aria-label="Tablica zadań" data-change="board"><option value="all" ${ui.board==='all'?'selected':''}>Wszystkie tablice</option>${boards.map(b=>`<option value="${b.id}" ${ui.board===b.id?'selected':''}>${esc(b.title)}</option>`).join('')}</select>${IB('plus','Nowa tablica','new-board')}<div class="segmented" style="margin-left:7px"><button data-action="task-view" data-value="kanban" class="${ui.taskView==='kanban'?'active':''}">${I('columns')} Kanban</button><button data-action="task-view" data-value="table" class="${ui.taskView==='table'?'active':''}">${I('table')} Tabela</button></div><span class="grow"></span><button class="btn small ${ui.filterTasks==='mine'?'soft':'quiet'}" data-action="filter-mine">${I('user')} Moje</button>${B(I('plus')+' Zadanie','new-task','','small primary')}</div>${ui.taskView==='kanban'?`<div class="board">${Object.entries(STATUSES).map(([status,label])=>`<section class="column" data-column="${status}"><div class="column-head"><span class="status-circle ${status}"></span>${label}<span class="count">${ts.filter(t=>t.status===status).length}</span><span class="grow"></span>${IB('plus','Dodaj: '+label,'new-task',`data-status="${status}"`)}</div>${ts.filter(t=>t.status===status).map(taskCard).join('')}<button class="add-card" data-action="new-task" data-status="${status}">${I('plus')} Dodaj zadanie</button></section>`).join('')}</div>`:`<div class="tasks-table-wrap"><table class="tasks-table"><thead><tr><th>Zadanie</th><th>Etap</th><th>Wykonawca</th><th>Termin</th><th>Nakład</th></tr></thead><tbody>${ts.map(t=>`<tr data-task="${t.id}" data-action="open-ref" data-ref="task:${t.id}" tabindex="0"><td><div class="task-name">${esc(t.title)}</div><div class="table-ref">${esc(db.boards[t.board]?.title)}${activeBlockers(t.id).length?' · Czeka na rozwiązanie':''}</div></td><td><span class="pill ${t.status==='doing'?'accent':t.status==='done'?'good':''}">${STATUSES[t.status]}</span></td><td>${t.assignee?avatar(t.assignee,true)+' '+esc(db.users[t.assignee].name):'—'}</td><td>${t.due?dateLabel(t.due):'—'}</td><td>${t.estimate?effortLabel(t):'—'}</td></tr>`).join('')}</tbody></table>${!ts.length?'<div class="empty">Brak zadań w tym widoku.</div>':''}</div>`}`}
function camera(){return ui.mapCameras[ui.map]||(ui.mapCameras[ui.map]={x:25,y:45,z:.8})}
function edgePath(e){let a=db.nodes[e.a],b=db.nodes[e.b];if(!a||!b)return '';let w=innerWidth<1150?200:210;let ah=document.querySelector(`[data-node="${a.id}"]`)?.offsetHeight||105,bh=document.querySelector(`[data-node="${b.id}"]`)?.offsetHeight||105;let ax=a.x+w/2,ay=a.y+ah/2,bx=b.x+w/2,by=b.y+bh/2;let dx=bx-ax,dy=by-ay;if(Math.abs(dx)>Math.abs(dy)*.85){ax+=Math.sign(dx)*w/2;bx-=Math.sign(dx)*w/2;let bend=Math.max(45,Math.abs(bx-ax)*.45);return `M ${ax} ${ay} C ${ax+Math.sign(dx)*bend} ${ay}, ${bx-Math.sign(dx)*bend} ${by}, ${bx} ${by}`}ay+=Math.sign(dy)*ah/2;by-=Math.sign(dy)*bh/2;let bend=Math.max(45,Math.abs(by-ay)*.45);return `M ${ax} ${ay} C ${ax} ${ay+Math.sign(dy)*bend}, ${bx} ${by-Math.sign(dy)*bend}, ${bx} ${by}`}
function nodeHTML(n){let ts=tasksForNode(n.id),result=ts.map(t=>resultMessage(t.id)).find(Boolean),anchor=anchorFor('node:'+n.id),count=anchor?replies(anchor).length:0,selected=ui.selected.includes(n.id);return `<div class="node ${n.root?'root':''} ${selected?'selected':''}" style="left:${n.x}px;top:${n.y}px" data-node="${n.id}" tabindex="0" role="group" aria-label="Myśl: ${esc(n.text)}">${selected&&ui.selected.length===1?`<div class="node-actions">${IB('chat','Rozmawiaj o tej myśli','open-ref',`data-ref="node:${n.id}"`)}${IB('send','Pokaż w rozmowie','share',`data-ref="node:${n.id}"`)}${IB('task','Podejmij zadanie','new-task',`data-nodes="${n.id}"`)}${IB('link','Połącz z istniejącą myślą','connect-start',`data-id="${n.id}"`)}${IB('more','Więcej opcji myśli','node-menu',`data-id="${n.id}"`)}</div>`:''}<div class="node-kind">${I(n.reference?kindIcon[n.reference.split(':')[0]]:n.root?'spark':'map')}${n.reference?'Odniesienie · '+kindName[n.reference.split(':')[0]]:n.root?'Wspólny pomysł':'Myśl'}</div><div class="node-text" data-node-text="${n.id}" spellcheck="true">${esc(titleOf('node:'+n.id))}</div>${ts.length||count||n.source?`<div class="node-meta">${ts.length?`<button data-action="open-ref" data-ref="task:${ts[0].id}">${I('task')}${ts.length} ${plural(ts.length,'zadanie','zadania','zadań')}</button>`:''}${count?`<button data-action="open-ref" data-ref="node:${n.id}">${I('chat')}${count}</button>`:''}${n.source?`<button data-action="jump-message" data-id="${n.source}">${I('reply')}Źródło</button>`:''}</div>`:''}${result?`<div class="node-result">${I('flag')} ${esc(short(plain(result.text),75))}</div>`:''}<button class="node-plus" data-action="node-child" data-id="${n.id}" title="Dopisz powiązaną myśl" aria-label="Dopisz powiązaną myśl">${I('plus')}</button></div>`}
function renderMap10(){let maps=Object.values(db.maps).filter(m=>m.space===ui.space);if(!maps.some(m=>m.id===ui.map))ui.map=maps[0]?.id;if(!ui.map)return `<div class="empty">${I('map')}<h3>Miejsce na pierwsze pomysły</h3><p>Mapa nie jest listą zobowiązań.</p><div style="margin-top:18px">${B(I('plus')+' Utwórz mapę','new-map','','primary')}</div></div>`;let ns=Object.values(db.nodes).filter(n=>n.map===ui.map&&!n.archived),es=Object.values(db.edges).filter(e=>e.map===ui.map&&ns.some(n=>n.id===e.a)&&ns.some(n=>n.id===e.b)),c=camera();return `<div class="toolbar"><select aria-label="Wybierz mapę" data-change="map">${maps.map(m=>`<option value="${m.id}" ${ui.map===m.id?'selected':''}>${esc(m.title)}</option>`).join('')}</select>${IB('plus','Nowa mapa','new-map')}<span class="grow"></span><div class="segmented"><button data-action="map-view" data-value="canvas" class="${ui.mapView==='canvas'?'active':''}">${I('map')}<span class="hide-mobile">Płótno</span></button><button data-action="map-view" data-value="list" class="${ui.mapView==='list'?'active':''}">${I('list')}<span class="hide-mobile">Lista</span></button></div>${ui.selected.length>1?B(I('task')+' Jeden krok z '+ui.selected.length+' myśli','new-task',`data-nodes="${ui.selected.join(',')}"`,'small soft'):''}${B(I('table')+' Ułóż','layout','','small')}${B(I('plus')+' Myśl','new-node','','small primary')}</div>${ui.mapView==='list'?`<div class="map-list">${ns.map(n=>`<div class="map-list-row"><div class="grow"><div class="eyebrow" style="margin-bottom:5px">${n.root?'Pomysł':'Myśl'}</div><button data-action="open-ref" data-ref="node:${n.id}" style="text-align:left;padding:0;font-size:13px">${esc(n.reference?titleOf(n.reference):n.text)}</button><p class="hint">${tasksForNode(n.id).length?tasksForNode(n.id).length+' zadań · ':''}${neighbors(n.id).length} połączeń</p></div>${IB('edit','Edytuj myśl','node-edit',`data-id="${n.id}"`)}${IB('plus','Dopisz myśl','node-child',`data-id="${n.id}"`)}</div>`).join('')}${!ns.length?'<div class="empty">Dodaj pierwszą myśl.</div>':''}${B(I('upload')+' Wklej listę myśli','paste-outline','','quiet')}</div>`:`<div class="map-shell"><div class="map-canvas" id="map-canvas" tabindex="0" aria-label="Mapa pomysłów. Przeciągnij tło, aby przesunąć. Shift i przeciągnięcie zaznacza grupę."><div class="map-world" id="map-world" style="transform:translate(${c.x}px,${c.y}px) scale(${c.z})"><svg class="edges">${es.map(e=>`<g data-edge="${e.id}"><path class="edge-hit" d="${edgePath(e)}" data-edge-hit="${e.id}"/><path class="edge-line ${ui.edge===e.id?'selected':''}" d="${edgePath(e)}"/></g>`).join('')}</svg>${ns.map(nodeHTML).join('')}</div></div>${ui.connect||ui.moveClick?`<div class="map-banner">${I(ui.connect?'link':'move')} ${ui.connect?'Kliknij drugą myśl. Połączymy je bez zmiany zadań.':'Kliknij nowe miejsce dla zaznaczonej myśli.'}${IB('x','Anuluj','cancel-map-mode')}</div>`:''}<div class="canvas-hint">Przeciągnij myśl lub tło · dwuklik edytuje · Shift zaznacza kilka</div><div class="canvas-controls">${IB('undo','Cofnij układ lub zmianę mapy','map-undo')}${IB('redo','Ponów zmianę mapy','map-redo')}<span style="width:1px;height:17px;background:var(--line);margin:0 5px"></span>${IB('minus','Oddal','zoom-out')}<span class="zoom-label">${Math.round(c.z*100)}%</span>${IB('plus','Przybliż','zoom-in')}${IB('fit','Pokaż całą mapę','map-fit')}</div></div>`}`}
function markdown(src){let lines=String(src||'').split('\n'),out=[],inCode=false,code=[],list=false;function inline(s){let rendered=textHTML(s);rendered=rendered.replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,(m,label,url)=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${label}${I('external')}</a>`);return rendered}for(let i=0;i<lines.length;i++){let line=lines[i];if(/^```/.test(line)){if(inCode){out.push('<pre><code>'+esc(code.join('\n'))+'</code></pre>');code=[]}else if(list){out.push('</ul>');list=false}inCode=!inCode;continue}if(inCode){code.push(line);continue}if(/^[-*] /.test(line)){if(!list){out.push('<ul>');list=true}out.push(`<li>${inline(line.slice(2))}</li>`);continue}if(list){out.push('</ul>');list=false}let h=line.match(/^(#{1,3}) (.+)/);if(h){out.push(`<h${h[1].length} data-line="${i}">${inline(h[2])}</h${h[1].length}>`);continue}if(line.startsWith('> ')){out.push('<blockquote>'+inline(line.slice(2))+'</blockquote>');continue}if(line.trim())out.push('<p data-line="'+i+'">'+inline(line)+'</p>')}if(list)out.push('</ul>');if(inCode)out.push('<pre><code>'+esc(code.join('\n'))+'</code></pre>');return out.join('')}
function pagePlain(page){let d=document.createElement('div');d.innerHTML=markdown(page.content);return d.textContent}
function fragmentStatus(f){let p=db.pages[f.page];if(!p)return {ok:false};let text=pagePlain(p),matches=[],idx=-1;while((idx=text.indexOf(f.quote,idx+1))>=0)matches.push(idx);if(matches.length===1)return {ok:true,index:matches[0]};let best=matches.filter(i=>(!f.prefix||text.slice(0,i).endsWith(f.prefix))&&(!f.suffix||text.slice(i+f.quote.length).startsWith(f.suffix)));return best.length===1?{ok:true,index:best[0]}:{ok:false}}
function renderWiki10(){let pages=Object.values(db.pages).filter(p=>p.space===ui.space&&!p.archived);if(!pages.some(p=>p.id===ui.page))ui.page=pages[0]?.id;let p=db.pages[ui.page];return `<div class="wiki-layout"><aside class="wiki-list"><div class="eyebrow" style="padding:8px 9px 14px">Pamięć projektu</div>${pages.map(page=>`<button class="wiki-page-item ${ui.page===page.id?'active':''}" data-action="page" data-id="${page.id}">${I('wiki')}${esc(page.title)}</button>`).join('')}<div class="wiki-side-actions" style="margin-top:14px">${B(I('plus')+' Nowa strona','new-page','','small quiet')}${B(I('upload')+' Importuj .md','import-md','','small quiet')}</div></aside><div class="wiki-main">${p?`${ui.wikiEdit?`<div class="wiki-head"><div><div class="eyebrow">Edycja Markdown</div><h2>${esc(p.title)}</h2></div><div class="row">${B('Anuluj','wiki-cancel','','small quiet')}${B('Zapisz wersję','wiki-save','','small primary')}</div></div><div class="wiki-edit"><input id="wiki-title" aria-label="Tytuł strony" data-preserve="wiki-title" value="${esc(ui.wikiDraft?.title??p.title)}"><textarea id="wiki-source" aria-label="Treść Markdown" data-preserve="wiki-source" spellcheck="false">${esc(ui.wikiDraft?.content??p.content)}</textarea><div class="row"><button class="btn small quiet" data-action="wiki-mention">@ Wskaż materiał</button><p class="hint">Markdown, bez wykonywania HTML. @ wstawia odnośnik do istniejącego materiału.</p></div></div>`:`<div class="wiki-head"><div class="row"><span class="pill">${I('wiki')} Wersja ${p.version}</span><span class="hint">${prefs().wikiDrafts?.[p.id]?'Masz niezapisany szkic — wróć przez Edytuj.':'Zaznacz tekst, aby wskazać dokładny fragment.'}</span></div><div class="row gap6">${IB('history','Historia strony','page-history',`data-id="${p.id}"`)}${IB('send','Pokaż stronę w rozmowie','share',`data-ref="page:${p.id}"`)}${IB('download','Eksportuj Markdown','export-md',`data-id="${p.id}"`)}${B(I('edit')+' Edytuj','wiki-edit','','small')}</div></div><article class="wiki-content" id="wiki-content" data-page="${p.id}">${markdown(p.content)}<div class="divider" style="margin-top:35px"></div><div class="row wrap">${B(I('chat')+' Rozmawiaj o stronie','open-ref',`data-ref="page:${p.id}"`,'small')}${B(I('quote')+' Wskaż fragment','quote-manual',`data-id="${p.id}"`,'small quiet')}${B(I('plus')+' Strona','new-page','','small quiet')}${B(I('upload')+' .md','import-md','','small quiet')}</div><div class="linked-group"><h4>Gdzie ta wiedza jest używana</h4>${pageUsage(p.id)}</div></article>`}`:`<div class="empty">${I('wiki')}<h3>Wiedza, do której warto wrócić</h3><p>Dodaj stronę lub wgraj plik Markdown.</p><div class="row" style="justify-content:center;margin-top:20px">${B(I('plus')+' Nowa strona','new-page','','primary')}${B(I('upload')+' Importuj .md','import-md')}</div></div>`}</div></div>`}
function pageUsage(id){let refs=['page:'+id,...Object.values(db.fragments).filter(f=>f.page===id).map(f=>'fragment:'+f.id)],uses=refs.flatMap(usageOf),dedup=[...new Map(uses.map(u=>[u.ref,u])).values()];return dedup.length?dedup.map(u=>`<button class="backlink" data-action="open-ref" data-ref="${u.ref}">${I(kindIcon[u.ref.split(':')[0]])}<span>${esc(short(titleOf(u.ref),80))}<br><span class="dim">${esc(u.reason)}</span></span></button>`).join(''):'<p class="hint">Wzmianki, zadania i odniesienia na mapie będą widoczne tutaj.</p>'}
function renderCoreHome(){let own=Object.values(db.tasks).filter(t=>allowed(t.space)&&t.assignee===ui.user&&t.status!=='done'),today=own.filter(t=>prefs().plan[t.id]===day()||t.due&&t.due<=day()),show=ui.homeFilter==='today'?today:own,resume=getObj(prefs().last),notifications=db.notifications.filter(n=>n.user===ui.user&&allowed(n.space)&&!n.read);let due=own.filter(t=>t.due===day());return `<div class="view-scroll"><div class="home"><div class="home-top"><div><div class="eyebrow" style="margin-bottom:12px">${new Date().toLocaleDateString('pl-PL',{weekday:'long',day:'numeric',month:'long'})}</div><h1>Hej, ${esc(db.users[ui.user].name)}.</h1><p>Nie musisz ogarniać wszystkiego. Wróć do jednego kroku.</p></div><span class="pill">${I('calendar')}${due.length?due.length+' '+plural(due.length,'termin dziś','terminy dziś','terminów dziś'):'Bez terminów na dziś'}</span></div>${resume&&allowed(resume.space)&&resume.status!=='done'?`<section class="resume-card"><div class="grow"><span class="eyebrow" style="color:var(--accent)">${I('pin')} Twój punkt powrotu</span><h2>${esc(resume.title||resume.text)}</h2><p>${esc(prefs().notes[resume.id]||'Kontekst i rozmowa są tam, gdzie je zostawiłeś.')}</p><div class="hint" style="margin-top:9px">${esc(db.spaces[resume.space].name)}</div></div>${B('Wróć do pracy '+I('arrow'),'open-ref',`data-ref="${prefs().last}"`,'primary')}</section>`:''}<div class="home-grid"><section class="home-section"><div class="row between" style="margin-bottom:12px"><h3 style="margin:0">Moja praca</h3><div class="segmented"><button class="${ui.homeFilter==='today'?'active':''}" data-action="home-filter" data-value="today">Na dziś</button><button class="${ui.homeFilter==='all'?'active':''}" data-action="home-filter" data-value="all">Wszystkie · ${own.length}</button></div></div><p class="hint">Wspólne terminy i Twój osobisty plan. Bez zadań reszty zespołu.</p>${show.length?show.map(t=>`<div class="home-task"><span class="status-circle ${t.status}"></span><div class="grow"><button class="title" data-action="open-ref" data-ref="task:${t.id}">${esc(t.title)}</button><div class="sub">${esc(db.spaces[t.space].name)}${t.due?' · Termin: '+dateLabel(t.due):''}${prefs().plan[t.id]===day()?' · Mój plan':''}</div></div>${activeBlockers(t.id).length?'<span class="pill warn">Czeka</span>':t.estimate?'<span class="pill">'+esc(effortLabel(t))+'</span>':''}</div>`).join(''):'<div class="empty"><p>Na dziś nie wybrałeś żadnego kroku.</p></div>'}</section><section class="home-section"><div class="row between"><h3 style="margin-bottom:0">Do Ciebie</h3>${notifications.length?`<span class="badge-number">${notifications.length}</span>`:''}</div><p class="hint" style="margin:9px 0">Odpowiedzi, wzmianki i prośby o pomoc.</p>${notifications.length?notifications.map(n=>`<button class="notification" data-action="open-notification" data-id="${n.id}">${I('chat')}<span><p>${esc(n.text)}</p><small>${esc(db.spaces[n.space].name)} · ${time(n.at)}</small></span></button>`).join(''):`<div class="empty">${I('check')}<p>Wszystko przeczytane.</p></div>`}</section></div></div></div>`}
function captureUI(){let active=document.activeElement,sel=window.getSelection(),a=null;if(active?.classList.contains('editor')){saveEditor(active);let range=sel?.rangeCount?sel.getRangeAt(0):null;let offset=0;if(range&&active.contains(range.startContainer)){let pre=range.cloneRange();pre.selectNodeContents(active);pre.setEnd(range.startContainer,range.startOffset);offset=pre.toString().length}a={key:active.dataset.key,offset};}else if(active?.dataset.preserve){a={preserve:active.dataset.preserve,value:active.type==='checkbox'?active.checked:active.value,start:active.selectionStart,end:active.selectionEnd}}let chat=$('#chat-scroll');return {active:a,chat:chat?{top:chat.scrollTop,bottom:chat.scrollHeight-chat.scrollTop-chat.clientHeight<70}:null,drawer:$('#drawer-scroll')?.scrollTop||0,view:$('.view-scroll')?.scrollTop||0}}
function caretAtText(el,offset){let walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT),n,last=null;while(n=walker.nextNode()){last=n;if(offset<=n.textContent.length){if(n.parentElement?.closest('[contenteditable=false]')){let token=n.parentElement.closest('[contenteditable=false]'),range=document.createRange();range.setStartAfter(token);range.collapse(true);let s=window.getSelection();s.removeAllRanges();s.addRange(range);return}let range=document.createRange();range.setStart(n,offset);range.collapse(true);let s=window.getSelection();s.removeAllRanges();s.addRange(range);return}offset-=n.textContent.length}let r=document.createRange();r.selectNodeContents(el);r.collapse(false);let s=window.getSelection();s.removeAllRanges();s.addRange(r)}
function render10(){let prev=captureUI();document.documentElement.dataset.theme=prefs().theme;document.documentElement.dataset.accent=prefs().accent;$('#app').innerHTML=`<div class="shell ${ui.menuOpen?'menu-open':''}">${renderSidebar()}<main class="main">${renderHeader()}${renderLiveBar()}<div class="workspace"><section class="view">${ui.view==='home'?renderHome():ui.view==='map'?renderMap():ui.view==='tasks'?renderTasks():ui.view==='wiki'?renderWiki():renderChat()}</section>${renderDrawer()}</div></main></div>`;
 if(ui.modal)renderModal();let chat=$('#chat-scroll');if(chat){if(ui.scrollEnd)chat.scrollTop=chat.scrollHeight;else if(prev.chat)chat.scrollTop=prev.chat.bottom?chat.scrollHeight:prev.chat.top}ui.scrollEnd=false;if($('#drawer-scroll'))$('#drawer-scroll').scrollTop=prev.drawer;if($('.view-scroll'))$('.view-scroll').scrollTop=prev.view;if(prev.active?.key){let ed=$(`.editor[data-key="${CSS.escape(prev.active.key)}"]`);if(ed){ed.focus({preventScroll:true});caretAtText(ed,prev.active.offset)}}else if(prev.active?.preserve){let el=$(`[data-preserve="${CSS.escape(prev.active.preserve)}"]`);if(el){if(el.type==='checkbox')el.checked=prev.active.value;else el.value=prev.active.value;el.focus({preventScroll:true});try{el.setSelectionRange(prev.active.start,prev.active.end)}catch(e){}}}requestAnimationFrame(()=>{updateEdgeGeometry();observeRead();if(ui.flash){let el=$(`[data-message="${ui.flash}"]`);el?.scrollIntoView({block:'center',behavior:'instant'})}})}
/* ---------- modal workflows: domain effects are explicit ---------- */
function modal(type,data={}){closeMenu();ui.modal={type,...data};renderModal();requestAnimationFrame(()=>{let el=$('#overlay input:not([type=checkbox]):not([type=file]),#overlay textarea,#overlay select');el?.focus()})}
function closeModal(){if(ui.modal?.type==='live'&&!ui.live)stopMedia();ui.modal=null;$('#overlay').innerHTML=''}
function modalShell(title,body,footer='',wide=false){$('#overlay').innerHTML=`<div class="backdrop" data-backdrop="true"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><h2 id="modal-title">${title}</h2>${IB('x','Zamknij okno','close-modal')}</header><div class="modal-content">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`}
function inputField(label,id,value='',type='text',extra=''){return `<div class="field"><label for="${id}">${label}</label><input type="${type}" id="${id}" value="${esc(value)}" ${extra}></div>`}
function selectTasks(id,selected='',filter=()=>true){return `<select id="${id}"><option value="">Wybierz zadanie…</option>${Object.values(db.tasks).filter(t=>t.space===ui.space&&filter(t)).map(t=>`<option value="${t.id}" ${t.id===selected?'selected':''}>${esc(t.title)}</option>`).join('')}</select>`}
function renderCoreModal(){if(!ui.modal){$('#overlay').innerHTML='';return}let m=ui.modal,body='',footer='',title='';let cancel=B('Anuluj','close-modal','','quiet');
 switch(m.type){
 case 'new-task':{title='Podejmij jeden krok';let source=m.source?db.messages[m.source]:null;body=`<p class="modal-description">Tytuł wystarczy. Resztę dodasz, gdy będzie potrzebna.</p>${inputField('Co konkretnie chcesz zrobić?','task-title',m.title||'')}${source?`<div class="notice">${I('chat')} Z wypowiedzi ${esc(db.users[source.author].name)}: „${esc(short(plain(source.text),120))}”</div>`:''}${m.nodeIds?.length?`<div class="notice" style="margin-top:10px">${I('map')} Jeden krok powiązany z ${m.nodeIds.length} ${plural(m.nodeIds.length,'myślą','myślami','myślami')}. Mapa nie zmieni się w listę zadań.</div>`:''}<details style="margin-top:15px"><summary class="hint" style="cursor:pointer">Miejsce i przypisanie</summary><div class="field"><label>Tablica</label><select id="task-board">${Object.values(db.boards).filter(b=>b.space===ui.space).map(b=>`<option value="${b.id}" ${b.id===ui.board?'selected':''}>${esc(b.title)}</option>`).join('')}</select></div></details><p class="hint" style="margin-top:15px">Powiązanie będzie widoczne przy źródle. Nie wysyłamy dodatkowej wiadomości bez Twojej decyzji.</p>`;footer=cancel+B('Dodaj','task-create','data-take="false"')+B('Dodaj i biorę '+I('arrow'),'task-create','data-take="true"','primary');break}
 case 'message-map':{let msg=db.messages[m.id];title='Rozwiń tę myśl na mapie';body=`<p class="modal-description">Powstanie edytowalna myśl z odnośnikiem do tej wypowiedzi. Wiadomość pozostanie bez zmian.</p>${inputField('Myśl na mapie','node-label',short(plain(msg.text),160))}<div class="field"><label>Na której mapie?</label><select id="target-map">${Object.values(db.maps).filter(p=>p.space===ui.space).map(p=>`<option value="${p.id}" ${p.id===ui.map?'selected':''}>${esc(p.title)}</option>`).join('')}<option value="new">+ Nowa mapa</option></select></div>`;footer=cancel+B('Dodaj na mapę','message-map-save',`data-id="${m.id}"`,'primary');break}
 case 'new-map':title='Nowa mapa';body=inputField('Nazwa robocza','map-title','Nowy szkic')+'<p class="hint">Możesz mieć kilka map. Nie zakładamy dla nich osobnych tablic zadań.</p>';footer=cancel+B('Utwórz mapę','map-create','','primary');break;
 case 'new-board':title='Nowa tablica';body=inputField('Jaką pracę chcesz tu zebrać?','board-title','')+'<p class="hint">Tablica jest zbiorem zadań. Kanban i tabela pokazują te same zadania. Dostęp dziedziczy projekt.</p>';footer=cancel+B('Utwórz tablicę','board-create','','primary');break;
 case 'node-edit':title='Edytuj myśl';body=`<textarea id="node-edit-text" rows="4">${esc(db.nodes[m.id]?.text)}</textarea>`;footer=cancel+B('Zapisz','node-edit-save',`data-id="${m.id}"`,'primary');break;
 case 'paste-outline':title='Wklej listę pomysłów';body='<p class="modal-description">Każda linia stanie się myślą. Wcięcia tworzą zwykłe połączenia. Bez tworzenia zadań.</p><textarea id="outline" rows="8" placeholder="Lampka\n  Kamera\n    Co po ciemku?\n  Czujnik"></textarea>';footer=cancel+B('Rozrysuj','outline-save','','primary');break;
 case 'layout':title='Ułóż mapę';body=`<p class="modal-description">Zmieniamy tylko położenie ${ui.selected.length>1?'zaznaczonych myśli':'myśli na tej mapie'}. Tekst, rozmowy i zadania pozostają bez zmian.</p><div class="stack">${B(I('map')+' Rozłóż połączenia od pierwszej myśli','layout-apply','data-layout="tree"')}${B(I('table')+' Równa siatka','layout-apply','data-layout="grid"')}${B(I('list')+' W jednym rzędzie','layout-apply','data-layout="row"')}</div><p class="hint" style="margin-top:15px">Możesz cofnąć układ jednym kliknięciem.</p>`;break;
 case 'task-edit':{let t=db.tasks[m.id];title='Opis zadania';body=inputField('Tytuł','edit-task-title',t.title)+`<div class="field"><label>Co ma powstać? Opcjonalnie.</label><div id="edit-task-description" class="editor" role="textbox" aria-label="Opis zadania" contenteditable="true" data-key="description:${t.id}" style="border:1px solid var(--line);border-radius:9px;padding:12px;min-height:130px">${textHTML(t.description,true)}</div><div style="margin-top:5px"><button class="btn small quiet" data-action="mention-open" data-key="description:${t.id}">@ Wskaż materiał</button></div></div><p class="hint">To opis aktualnego działania, nie komentarz. Odnośnik w treści jest wzmianką. „Powiąż materiał” dodaje źródło do stałego kontekstu zadania.</p>`;footer=cancel+B('Zapisz','task-edit-save',`data-id="${t.id}"`,'primary');break}
 case 'task-due':title='Termin ukończenia';body='<p class="modal-description">Wspólny termin widoczny dla projektu. Nie zmienia Twojego osobistego planu ani nakładu.</p>'+inputField('Do kiedy chcecie to zakończyć?','date-input',db.tasks[m.id]?.due||'','date');footer=B('Usuń termin','date-save',`data-id="${m.id}" data-kind="due" data-clear="true"`,'quiet')+B('Zapisz termin','date-save',`data-id="${m.id}" data-kind="due"`,'primary');break;
 case 'task-plan':title='Mój plan';body='<p class="modal-description">Tylko dla Ciebie. Pokażemy krok na „U mnie”, nie zmieniając wspólnego deadline’u.</p>'+inputField('Kiedy chcesz nad tym popracować?','date-input',prefs().plan[m.id]||day(),'date');footer=B('Usuń z planu','date-save',`data-id="${m.id}" data-kind="plan" data-clear="true"`,'quiet')+B('Zapisz mój plan','date-save',`data-id="${m.id}" data-kind="plan"`,'primary');break;
 case 'task-estimate':title='Orientacyjny nakład';body='<p class="modal-description">Pomaga wybrać krok na dostępną chwilę. To nie termin i nie zobowiązanie.</p><div class="row wrap">'+[15,30,60,120].map(v=>B(v<60?v+' min':v/60+' h','estimate-save',`data-id="${m.id}" data-value="${v}"`,'soft')).join('')+'</div>';footer=B('Jeszcze nie wiem','estimate-save',`data-id="${m.id}" data-value="0"`,'quiet');break;
 case 'task-assignee':title='Kto bierze ten krok?';body=`<select id="assignee-select"><option value="">Nikt jeszcze</option>${db.spaces[ui.space].members.map(u=>`<option value="${u}" ${db.tasks[m.id].assignee===u?'selected':''}>${esc(db.users[u].name)}</option>`).join('')}</select><p class="hint" style="margin-top:12px">Wskazanie wykonawcy nie zmienia dostępu do projektu.</p>`;footer=cancel+B('Zapisz','assignee-save',`data-id="${m.id}"`,'primary');break;
 case 'resume-edit':title='Mój punkt powrotu';body='<p class="modal-description">Twoja prywatna notatka na „U mnie”. Nie publikuje komentarza i nie blokuje zadania.</p>'+`<textarea id="resume-text" rows="4" placeholder="Następnym razem zacznij od…">${esc(prefs().notes[m.id]||'')}</textarea>`;footer=cancel+B('Zostaw na później','resume-save',`data-id="${m.id}"`,'primary');break;
 case 'reminder':title='Osobiste przypomnienie';body='<p class="modal-description">Przypomnienie pojawi się na „U mnie”, gdy aplikacja jest otwarta. Bez push i działania po zamknięciu pliku.</p>'+inputField('Przypomnij mi w dniu','date-input',prefs().reminders[m.id]?.date||db.tasks[m.id].due||day(),'date');footer=B('Usuń','reminder-save',`data-id="${m.id}" data-clear="true"`,'quiet')+B('Ustaw przypomnienie','reminder-save',`data-id="${m.id}"`,'primary');break;
 case 'task-move':title='Przenieś zadanie';body='<p class="modal-description">Ten sam identyfikator, rozmowa i powiązania. Bez kopiowania zadania.</p>'+`<select id="board-select">${Object.values(db.boards).filter(b=>b.space===ui.space).map(b=>`<option value="${b.id}" ${db.tasks[m.id].board===b.id?'selected':''}>${esc(b.title)}</option>`).join('')}</select>`;footer=cancel+B('Przenieś','task-move-save',`data-id="${m.id}"`,'primary');break;
 case 'mark':{let msg=db.messages[m.id],ts=relatedTasksToMessage(m.id),selected=m.task||(ts.length===1?ts[0].id:'');title=m.kind==='blocker'?'Ta wiadomość blokuje…':m.kind==='result'?'Zapisz tę wiadomość jako wynik':'Co rozwiązuje ta wiadomość?';body=`<div class="quote-preview" style="font-size:12px;margin-top:0">${esc(short(plain(msg.text),220))}</div>`;if(m.kind==='solution'){let blockers=Object.values(db.effects).filter(e=>e.kind==='blocker'&&!e.resolvedAt&&db.tasks[e.task]?.space===ui.space&&e.message!==msg.id);body+=`<label>Rozwiązana przeszkoda lub pytanie</label><select id="solution-select"><option value="">Wybierz, co zostało rozwiązane…</option>${msg.parent?`<option value="question:${msg.parent}">Pytanie, na które odpowiadam</option>`:''}${blockers.map(e=>`<option value="${e.id}">${esc(db.tasks[e.task].title)} · ${esc(short(db.messages[e.message]?.text,55))}</option>`).join('')}</select><p class="hint" style="margin-top:12px">Rozwiązanie usuwa wybraną przeszkodę, nie kończy zadania i nie usuwa pozostałych blockerów.</p>`;}else{body+=`<div class="field"><label>Wskaż zadanie</label>${selectTasks('effect-task',selected,t=>m.kind!=='blocker'||t.status!=='done')}</div>`;if(m.kind==='blocker')body+=`<label>Od kogo potrzebujesz pomocy? Opcjonalnie.</label><select id="effect-helper"><option value="">Nie wskazuję osoby</option>${db.spaces[ui.space].members.filter(u=>u!==ui.user).map(u=>`<option value="${u}">${esc(db.users[u].name)}</option>`).join('')}</select><p class="hint" style="margin-top:12px">Ta sama wypowiedź będzie powodem blokady. Nie tworzymy kopii komentarza.</p>`;else body+='<label class="checkbox"><input type="checkbox" id="effect-finish"> Zakończ też zadanie</label><p class="hint">Wynik pojawi się przy zadaniu i powiązanych myślach. Nie jest automatycznie decyzją projektu.</p>';}footer=cancel+B(m.kind==='blocker'?'Oznacz przeszkodę':m.kind==='result'?'Zapisz wynik':'Oznacz rozwiązanie','effect-save',`data-id="${m.id}" data-kind="${m.kind}"`,'primary');break}
 case 'resolve':{let e=db.effects[m.id];title='Rozwiąż przeszkodę';body=`<div class="quote-preview" style="margin-top:0;font-size:12px">${esc(db.messages[e.message]?.text)}</div><label>Co pozwala wrócić do pracy?</label><textarea id="resolve-text" rows="3" placeholder="Dostęp jest już gotowy…"></textarea><p class="hint" style="margin-top:12px">Opublikujemy odpowiedź przy zadaniu i rozwiążemy tylko tę przeszkodę. Nie zakończymy zadania.</p>`;footer=cancel+B('Wyślij i odblokuj','resolve-save',`data-id="${m.id}"`,'primary');break}
 case 'unmark-message':{title='Cofnij oznaczenie';let effects=Object.values(db.effects).filter(e=>e.message===m.id&&!e.cancelledAt);body='<p class="modal-description">Wiadomość pozostanie w rozmowie. Cofnięcie wyniku nie zmieni automatycznie stanu wykonania zadania.</p><select id="unmark-select">'+(db.messages[db.messages[m.id].parent]?.solution===m.id?'<option value="answer">Rozwiązanie pytania</option>':'')+effects.map(e=>`<option value="${e.id}">${e.kind==='blocker'?'Przeszkoda':e.kind==='result'?'Wynik':'Rozwiązanie'} · ${esc(db.tasks[e.task]?.title)}</option>`).join('')+'</select>';footer=cancel+B('Cofnij oznaczenie','unmark-save',`data-id="${m.id}"`,'primary');break;}
 case 'message-edit':title='Edytuj wiadomość';body=`<div id="message-edit-text" class="editor" contenteditable="true" role="textbox" aria-label="Edytuj treść wiadomości" data-key="edit:${m.id}" style="border:1px solid var(--line);border-radius:9px;padding:12px;min-height:130px">${textHTML(db.messages[m.id].text,true)}</div><button class="btn small quiet" data-action="mention-open" data-key="edit:${m.id}" style="margin-top:6px">@ Wskaż materiał</button><p class="hint" style="margin-top:10px">Źródła i oznaczenia pozostają. Propozycje agenta oparte na poprzedniej treści staną się nieaktualne.</p>`;footer=cancel+B('Zapisz zmianę','message-edit-save',`data-id="${m.id}"`,'primary');break;
 case 'new-page':title='Nowa strona wiki';body=inputField('Tytuł','page-title','');footer=cancel+B('Utwórz i pisz','page-create','','primary');break;
 case 'page-history':{let p=db.pages[m.id];title='Historia · '+esc(p.title);body=p.history.length?p.history.slice().reverse().map(h=>`<div class="settings-row"><div><p>Wersja ${h.version} · ${esc(h.title)}</p><small>${new Date(h.at).toLocaleString('pl-PL')}</small></div>${B('Przywróć','page-restore',`data-id="${p.id}" data-version="${h.version}"`,'small')}</div>`).join(''):'<p class="hint">To pierwsza wersja tej strony.</p>';body+='<p class="hint" style="margin-top:15px">Przywrócenie tworzy kolejną wersję. Nie usuwa historii.</p>';break}
 case 'quote-manual':title='Wskaż dokładny fragment';body='<p class="modal-description">Zaznacz tekst bezpośrednio na stronie lub wklej tu cytat, który występuje w niej dokładnie raz.</p><textarea id="quote-text" rows="4" placeholder="Fragment dokumentu…"></textarea>';footer=cancel+B('Utwórz odnośnik do fragmentu','quote-save',`data-id="${m.id}"`,'primary');break;
 case 'link-task':{let t=db.tasks[m.id];title='Materiały do tego zadania';body='<p class="modal-description">Wybierz konkretne myśli i źródła. Sąsiednie elementy mapy nie zostaną przypięte automatycznie.</p>';for(let [label,refs] of [['Myśli',Object.values(db.nodes).filter(n=>n.space===ui.space&&!n.archived).map(n=>'node:'+n.id)],['Wiki i fragmenty',[...Object.values(db.pages).filter(p=>p.space===ui.space).map(p=>'page:'+p.id),...Object.values(db.fragments).filter(f=>f.space===ui.space).map(f=>'fragment:'+f.id)]]])body+=`<div class="eyebrow" style="margin:20px 0 8px">${label}</div>${refs.map(r=>`<label class="checkbox"><input type="checkbox" name="task-link" value="${r}" ${t.references.includes(r)||r.startsWith('node:')&&t.nodeIds.includes(r.split(':')[1])?'checked':''}> ${I(kindIcon[r.split(':')[0]])}<span>${esc(short(titleOf(r),90))}</span></label>`).join('')}`;footer=cancel+B('Zapisz powiązania','task-links-save',`data-id="${m.id}"`,'primary');break}
 case 'ref-task':title='Wskaż w zadaniu';body=material(m.ref)+'<div class="field"><label>Do którego zadania?</label>'+selectTasks('reference-task')+'</div><p class="hint">Dodamy źródło do zadania. Nie zmienimy jego statusu ani nie skopiujemy dokumentu.</p>';footer=cancel+B('Powiąż źródło','reference-task-save',`data-ref="${m.ref}"`,'primary');break;
 case 'ref-map':title='Pokaż materiał na mapie';body=material(m.ref)+`<div class="field"><label>Mapa</label><select id="target-map">${Object.values(db.maps).filter(mp=>mp.space===ui.space).map(mp=>`<option value="${mp.id}" ${mp.id===ui.map?'selected':''}>${esc(mp.title)}</option>`).join('')}<option value="new">+ Nowa mapa</option></select></div><p class="hint">To odniesienie do materiału, nie niezależna kopia treści.</p>`;footer=cancel+B('Dodaj odniesienie','reference-map-save',`data-ref="${m.ref}"`,'primary');break;
 case 'new-project':{title=m.fromDM?'Rozwijamy osobno':'Nowy projekt';body=inputField('Nazwa robocza','project-name',m.fromDM?'Poboczny pomysł':'')+inputField('Najbliższy efekt · opcjonalnie','project-goal','')+'<label>Z kim to robisz?</label>';let members=m.fromDM?db.spaces[ui.space].members:[ui.user];body+=Object.entries(db.users).filter(([id])=>id!=='ai'&&!db.users[id].historical).map(([id,u])=>`<label class="checkbox"><input type="checkbox" name="project-member" value="${id}" ${members.includes(id)?'checked':''} ${id===ui.user||m.fromDM?'disabled':''}>${esc(u.name)}${id===ui.user?' (Ty)':''}</label>`).join('');body+='<p class="hint" style="margin-top:12px">Projekt ma własne grono. Nie dziedziczy uczestników innych projektów.</p>';if(m.fromDM)body+='<div class="notice" style="margin-top:12px">Przeniesiemy tylko wskazaną wiadomość jako jawny materiał startowy. Reszta DM pozostaje prywatna i nie synchronizuje się.</div>';footer=cancel+B('Utwórz projekt','project-create','','primary');break}
 case 'new-dm':title='Napisz prywatnie';body='<p class="modal-description">Osobna rozmowa. Nie dodajemy tej osoby do Twoich projektów.</p>'+Object.entries(db.users).filter(([id])=>id!=='ai'&&id!==ui.user).map(([id,u])=>`<button class="search-item" data-action="dm-create" data-id="${id}">${avatar(id)}${esc(u.name)} ${I('arrow')}</button>`).join('');break;
 case 'project-settings':{let s=db.spaces[ui.space];title='Ustawienia · '+esc(s.name);body=inputField('Nazwa','project-name',s.name)+inputField('Najbliższy efekt','project-goal',s.goal||'')+`<div class="settings-row"><div><p>Pomoc w tle</p><small>Regułowy agent demo proponuje dopisanie wyników do wiki.</small></div><input type="checkbox" id="project-ai" ${s.ai?'checked':''} aria-label="Pomoc agenta w tle"></div><div class="settings-section"><h3>Osoby w tym projekcie</h3><div class="row" style="margin-top:12px">${s.members.map(u=>`<span class="row gap6">${avatar(u,true)}<span class="small">${esc(db.users[u].name)}</span></span>`).join('')}</div><p class="hint" style="margin-top:12px">Lokalna demonstracja grona, nie autoryzacja serwerowa. Członkostwo ustalasz przy tworzeniu projektu.</p></div><div class="notice">MCP, Git/CI, SSO i rozszerzenia są opisane w README. Ten plik nie łączy się z dostawcami ani nie prosi o sekrety.</div>`;footer=cancel+B('Zapisz','project-settings-save','','primary');break}
 case 'settings':{title='Twój Flux';let tab=ui.settingsTab;body=`<div class="row wrap" style="margin-bottom:22px">${[['appearance','Wygląd'],['notifications','Powiadomienia'],['data','Dane i demo']].map(([v,l])=>`<button class="settings-tab ${tab===v?'active':''}" data-action="settings-tab" data-value="${v}">${l}</button>`).join('')}</div>`;if(tab==='appearance'){body+='<h3>Tło</h3><p class="hint" style="margin:6px 0 15px">Jedna z dwóch dopracowanych baz. Ustawienie tylko dla Ciebie.</p><div class="theme-options">'+[['light','Jasne'],['dark','Ciemne']].map(([v,l])=>`<button class="theme-option ${prefs().theme===v?'selected':''}" data-action="theme-set" data-value="${v}" aria-pressed="${prefs().theme===v}"><div class="theme-preview ${v}"><div class="sidebar-preview"></div><div class="chat-preview"><span></span><span></span><span></span></div></div>${l}</button>`).join('')+'</div><h3 style="margin-top:26px">Akcent</h3><p class="hint" style="margin-top:6px">Gotowe palety — dobrane osobno dla jasnego i ciemnego tła. Bez własnego HEX i kolorów organizacji.</p><div class="swatches">'+[['iris','Irys','#ac95ed'],['amber','Miód','#e6bd71'],['mint','Mięta','#82c8a9'],['sky','Niebo','#85bbed'],['rose','Róża','#dca1be']].map(([v,l,c])=>`<button class="swatch ${prefs().accent===v?'active':''}" data-action="accent-set" data-value="${v}" aria-label="Akcent ${l}" aria-pressed="${prefs().accent===v}"><span class="dot" style="--sample:${c}"></span>${l}</button>`).join('')+'</div><div class="notice" style="margin-top:24px">Kolor wspiera hierarchię. „Przeszkoda”, „wynik” i „rozwiązanie” mają też nazwy oraz ikony — nie są rozróżniane wyłącznie barwą.</div>';}else if(tab==='notifications'){body=`<h3>Co trafia do „U mnie”</h3>${[['mentions','Wzmianki i wiadomości prywatne'],['replies','Odpowiedzi na moje wypowiedzi']].map(([key,label])=>`<div class="settings-row"><p>${label}</p><input type="checkbox" data-change="notify" data-key="${key}" ${prefs().notify[key]!==false?'checked':''} aria-label="${label}"></div>`).join('')}<div class="notice" style="margin-top:20px">Bez dzwonków i powiadomień push. Przypomnienia w tej wersji działają tylko przy otwartym HTML-u.</div>`;}else body=`<div class="settings-row"><div><p>Zapis w przeglądarce</p><small>${storeOK?'Dostępny. Dane Studio 11 nie nadpisują wcześniejszej wersji.':'Niedostępny: '+esc(storeError)}</small></div><span class="pill ${storeOK?'good':'warn'}">${storeOK?'Lokalnie':'Tylko pamięć'}</span></div><div class="row wrap" style="margin-top:20px">${B(I('download')+' Eksport JSON','export')}${B(I('upload')+' Import JSON','import-json')}</div><div class="settings-section"><h3>Wyświetlany profil demo</h3><p class="hint">Wszystkie dane są w tym pliku. Przełączenie profilu nie jest logowaniem ani zabezpieczeniem.</p><select data-change="demo-user" style="margin-top:10px">${Object.entries(db.users).filter(([id])=>id!=='ai'&&!db.users[id].historical).map(([id,u])=>`<option value="${id}" ${ui.user===id?'selected':''}>${esc(u.name)}</option>`).join('')}</select></div>${B('Przywróć przykładowe dane','reset-confirm','','danger')}<p class="hint" style="margin-top:14px">Eksportuj pracę przed resetem. Import rozpoznaje archiwum projektu Studio 11 oraz pełny backup schematu 09, 10 lub 11. Nie migruje v8.</p>`;break}
 case 'search':title='Znajdź we Fluxie';body=`<div class="row">${I('search')}<input class="search-input" id="global-search" placeholder="Wiadomość, zadanie, myśl, wiki…" autocomplete="off"></div><div class="divider"></div><div id="search-results" class="search-results">${searchResults('')}</div>`;break;
 case 'reset-confirm':title='Przywrócić dane przykładowe?';body='<p class="modal-description">Usunie to zmiany zapisane w tej wersji HTML-u. Wcześniejsze wersje Fluxa pozostają bez zmian.</p>';footer=cancel+B('Najpierw eksportuj','export')+B('Przywróć demo','reset-now','','danger');break;
 case 'import-confirm':title='Zastąpić lokalne dane?';body=`<p class="modal-description">Import ma ${Object.keys(m.data.spaces).length} miejsc i ${Object.keys(m.data.messages).length} wiadomości. Zastąpi aktualny stan — nie scala dwóch kopii.</p>`;footer=cancel+B('Zastąp po imporcie','import-apply','','primary');break;
 case 'about':title='Flux · Studio 11';body=`<p class="modal-description">Rozmowa zaczyna pracę. Mapa pozwala myśleć. Zadanie oznacza zobowiązanie. Wiki zachowuje to, co warto wiedzieć.</p><div class="stack">${['Jedna rozmowa projektu, bez obowiązkowych tematów.','Odpowiedzi przy wiadomości, bez nieskończonych podwątków.','Przeszkoda, rozwiązanie i wynik mają jawne skutki.','Materiał ma jeden identyfikator, nie cztery synchronizowane kopie.'].map(t=>`<div class="row small">${I('check')}${esc(t)}</div>`).join('')}</div><div class="notice warning" style="margin-top:22px">To działająca lokalna aplikacja demonstracyjna. Bez wieloosobowej synchronizacji, serwerowych uprawnień, rzeczywistego AI, MCP i połączeń głosowych. Nie używaj do poufnych danych.</div><div class="settings-section"><h3>Skróty są dodatkiem, nie wymaganiem</h3><p class="hint">Enter — wyślij · Shift Enter — nowa linia · @ — materiał lub osoba · Ctrl K — szukaj · Escape — zamknij · na mapie: Shift zaznacza grupę, strzałki przesuwają.</p></div>`;break;
 case 'live':title='Spójrzmy na to razem';body=`<p class="modal-description">Sesja przy aktualnej pracy, nie osobny pokój. W tej wersji testujesz tylko własne urządzenia — nikt Cię nie słyszy ani nie ogląda.</p><div class="notice">${I('headphones')} ${ui.live?'Obecność lokalna jest aktywna.':'Dołączenie nie włącza mikrofonu ani kamery.'}</div><div class="row wrap" style="margin-top:18px">${B(I('mic')+(ui.streams.audio?' Wyłącz mikrofon':' Test mikrofonu'),'media-toggle','data-kind="audio"')}${B(I('camera')+(ui.streams.video?' Wyłącz kamerę':' Test kamery'),'media-toggle','data-kind="video"')}${B(I('screen')+(ui.streams.screen?' Zatrzymaj ekran':' Test ekranu'),'media-toggle','data-kind="screen"')}</div><video id="live-video" class="live-preview" autoplay muted playsinline ${ui.streams.video||ui.streams.screen?'':'hidden'}></video><p class="hint" style="margin-top:12px">Nie ma nagrywania, transkrypcji ani transmisji. „Wyjdź” zatrzyma wszystkie testowane urządzenia.</p>`;footer=B(ui.live?'Wyjdź':'Zamknij','leave-live','','quiet')+(!ui.live?B('Wejdź lokalnie','start-live','','primary'):'');break;
 default:title='Nieznana czynność';body='<p>Nie zmieniono danych.</p>';
 }modalShell(title,body,footer,m.type==='settings'||m.type==='link-task');if(m.type==='live'){let v=$('#live-video');if(v&&(ui.streams.screen||ui.streams.video))v.srcObject=ui.streams.screen||ui.streams.video}}
/* ---------- interaction ---------- */
function toast(text,action=null){let id=uid('toast'),el=document.createElement('div');el.className='toast';el.id=id;el.innerHTML=I('check')+'<span>'+esc(text)+'</span>'+(action?`<button data-action="${action}">Cofnij</button>`:'');$('#toasts').appendChild(el);setTimeout(()=>el.remove(),5400)}
function setSpace10(id){captureUI();if(!allowed(id)){toast('Nie masz dostępu do tego miejsca.');return false}ui.space=id;ui.view='chat';ui.drawer=null;ui.map=Object.values(db.maps).find(m=>m.space===id)?.id;ui.page=Object.values(db.pages).find(p=>p.space===id)?.id;ui.board=Object.values(db.boards).find(b=>b.space===id)?.id||'all';ui.selected=[];ui.edge=null;ui.wikiEdit=false;ui.connect=null;ui.menuOpen=false;ui.scrollEnd=true;ui.flash=null;ui.composerMode='normal';closeMenu();return true}
function openRef(ref){let o=getObj(ref);if(!o){toast('Materiał nie jest już dostępny.');return}if(ref.startsWith('person:')){startDM(ref.split(':')[1]);return}if(!allowed(o.space)){toast('Materiał nie jest dostępny dla tego profilu.');return}if(ui.space!==o.space){if(!setSpace(o.space))return}let type=ref.split(':')[0];if(type==='message'){jumpMessage(o.id);return}if(ui.view==='home')ui.view='chat';ui.drawer={kind:'object',ref};ui.drawerTab='talk';if($('#drawer-scroll'))$('#drawer-scroll').scrollTop=0;ui.composerMode='normal';if(type==='node'){ui.view='map';ui.map=o.map;ui.selected=[o.id];ui.edge=null;if(ui.mapView==='canvas')requestAnimationFrame(()=>fitMap([o.id]))}if(type==='edge'){ui.view='map';ui.map=o.map;ui.edge=o.id;ui.selected=[]}if(type==='task'){prefs().last=ref;persist()}render()}
function jumpMessage(id){let m=db.messages[id];if(!m||!allowed(m.space)){toast('Wiadomość niedostępna.');return}if(ui.space!==m.space)setSpace(m.space);ui.view='chat';ui.flash=rootId(m.id);ui.scrollEnd=false;if(m.parent)ui.drawer={kind:'comments',id:m.parent};else ui.drawer=null;ui.composerMode='normal';render();setTimeout(()=>{if(ui.flash===rootId(m.id)){ui.flash=null;$$('.msg.highlight').forEach(x=>x.classList.remove('highlight'))}},3500)}
function openComments(id){let r=rootId(id);ui.drawer={kind:'comments',id:r};ui.composerMode='normal';ui.drawerTab='talk';render();let ed=$(`.editor[data-key="reply:${CSS.escape(r)}"]`);ed?.focus()}
function startDM(user){if(user===ui.user){toast('Do własnych myśli użyj szkicownika.');return}let d=Object.values(db.spaces).find(s=>s.kind==='dm'&&s.members.length===2&&s.members.includes(ui.user)&&s.members.includes(user));if(!d){let id=uid('dm');d={id,name:db.users[user].name,kind:'dm',members:[ui.user,user],goal:'',icon:'user',ai:false};db.spaces[id]=d;persist()}closeModal();setSpace(d.id);render()}
function closeMenu(){ui.menu=null;ui.mention=null;$('#popover').innerHTML=''}
function menuAt(el,items){let r=el?.getBoundingClientRect()||{left:innerWidth/2,top:innerHeight/2,bottom:innerHeight/2};closeMenu();$('#popover').innerHTML=`<div class="menu" role="menu">${items.map(it=>it.label?`<div class="menu-label">${esc(it.label)}</div>`:`<button data-action="${it.action}" ${it.data||''} role="menuitem">${I(it.icon||'arrow')}<span>${esc(it.text)}${it.sub?'<span class="menu-sub">'+esc(it.sub)+'</span>':''}</span></button>`).join('')}</div>`;let node=$('#popover .menu');node.style.left=Math.min(innerWidth-node.offsetWidth-10,Math.max(8,r.left))+'px';node.style.top=Math.max(8,Math.min(innerHeight-node.offsetHeight-10,r.bottom+5))+'px';ui.menu=true}
function serializeEditor(root){function walk(n){if(n.nodeType===Node.TEXT_NODE)return n.textContent.replace(/\u00a0/g,' ');if(n.nodeType!==Node.ELEMENT_NODE)return '';if(n.hasAttribute('data-ref'))return '[['+n.dataset.ref+']]';if(n.tagName==='BR')return '\n';let text=[...n.childNodes].map(walk).join('');if((n.tagName==='DIV'||n.tagName==='P')&&n!==root)return '\n'+text;return text}return [...root.childNodes].map(walk).join('').replace(/^\n/,'').replace(/\n{3,}/g,'\n\n')}
function saveEditor(el){if(!el?.dataset.key)return;prefs().drafts[el.dataset.key]=serializeEditor(el)}
function editorFor(key){return $(`.editor[data-key="${CSS.escape(key)}"]`)}
function sendEditor(key,taskId=null){let el=editorFor(key);if(!el)return;saveEditor(el);let text=prefs().drafts[key]||'',files=ui.attachments[key]||[],share=ui.pendingShares?.[key];if(!text.trim()&&!files.length&&!share){toast('Napisz coś lub wskaż materiał.');el.focus();return}let success=false;let newM=null;let mode=taskId?ui.composerMode:'normal';let helper=$('#composer-helper')?.value||null,finish=$('#composer-finish')?.checked||false;
 success=transact('message.publish',()=>{let parent=null;if(key.startsWith('reply:'))parent=key.slice(6);if(key.startsWith('entity:'))parent=ensureAnchor(key.slice(7));if(/^\/ai(?:\s|$)/i.test(text)){newM=runAI(text,parent)}else{newM=createMessage({text,parent,files,primary:share||null});if(share&&!db.anchors[share]){db.anchors[share]=newM.id;if(share.startsWith('task:'))db.tasks[share.split(':')[1]].anchor=newM.id}if(mode==='blocker')markBlocker(newM.id,taskId,helper);if(mode==='result')setResult(taskId,newM.id,finish)}prefs().drafts[key]='';ui.attachments[key]=[];if(ui.pendingShares)delete ui.pendingShares[key];el.innerHTML='';ui.composerMode='normal';ui.scrollEnd=key.startsWith('chat:');},{renderUI:false});if(success){render();let ed=editorFor(key);ed?.focus({preventScroll:true});let sc=$('#drawer-scroll');if(!key.startsWith('chat:')&&sc)sc.scrollTop=sc.scrollHeight}}
function shareRef10(ref){if(!canRef(ref)){toast('Nie można udostępnić materiału w tym gronie.');return}let anchor=anchorFor(ref);if(anchor){jumpMessage(anchor);toast('Materiał jest już w rozmowie. Otworzyłem jego kartę.');return}captureUI();ui.view='chat';ui.drawer=null;ui.pendingShares=ui.pendingShares||{};let key='chat:'+ui.space;ui.pendingShares[key]=ref;ui.scrollEnd=true;render();editorFor(key)?.focus();toast('Gotowe do wysłania. Udostępnisz dopiero po kliknięciu strzałki.')}
function insertRefAtEnd(ref,key=contextKey()){let el=editorFor(key);if(!el){prefs().drafts[key]=(prefs().drafts[key]||'')+'[['+ref+']] ';render();return}el.focus();let span=document.createElement('span');span.innerHTML=renderRef(ref,true);el.appendChild(span.firstChild);el.appendChild(document.createTextNode(' '));saveEditor(el);caretAtText(el,el.textContent.length);persist()}
function allCandidates(space=ui.space,global=false){let arr=[];const accept=o=>global?allowed(o.space):o.space===space;for(let [type,col]of [['task','tasks'],['node','nodes'],['map','maps'],['page','pages'],['fragment','fragments'],['message','messages']])for(let o of Object.values(db[col]))if(accept(o)&&!o.archived&&!(type==='message'&&o.author==='ai'))arr.push({ref:type+':'+o.id,type,title:titleOf(type+':'+o.id),space:o.space,sub:descriptionOf(type+':'+o.id)});if(!global)for(let id of db.spaces[space].members)arr.push({ref:'person:'+id,type:'person',title:db.users[id].name,space,sub:'Osoba w tym gronie'});return arr}
function norm(s){return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ł/g,'l')}
function detectMention(el,force=false){let sel=window.getSelection(),range=sel?.rangeCount?sel.getRangeAt(0):null;if(!range||!el.contains(range.startContainer)){if(!force)return;el.focus();caretAtText(el,el.textContent.length);range=window.getSelection().getRangeAt(0)}let match=null,replaceRange=range.cloneRange();if(range.startContainer.nodeType===3){let text=range.startContainer.textContent.slice(0,range.startOffset);match=text.match(/(?:^|\s)@([^\s@]*)$/);if(match){replaceRange.setStart(range.startContainer,range.startOffset-(match[1].length+1));replaceRange.setEnd(range.startContainer,range.startOffset)}}if(!match&&!force){if(ui.mention)closeMenu();return}let q=match?.[1]||'',options=allCandidates().filter(c=>norm(c.title+' '+kindName[c.type]).includes(norm(q))).slice(0,9);ui.mention={key:el.dataset.key,range:replaceRange,options,index:0};renderMention(el)}
function renderMention(el){let a=ui.mention;if(!a)return;let r=el.closest('.composer')?.getBoundingClientRect()||el.getBoundingClientRect();$('#popover').innerHTML=`<div class="menu mention-menu" role="listbox" aria-label="Osoby i materiały"><div class="menu-label">W tym gronie · ↑ ↓ wybierz · Enter wstaw</div>${a.options.length?a.options.map((c,i)=>`<button role="option" aria-selected="${i===a.index}" class="${i===a.index?'selected':''}" data-action="mention-pick" data-index="${i}">${I(kindIcon[c.type])}<span><span class="type">${kindName[c.type]}</span>${esc(short(c.title,65))}<span class="menu-sub">${esc(short(c.sub,65))}</span></span></button>`).join(''):'<div class="empty" style="padding:15px">Brak materiału. Nie tworzymy go automatycznie.</div>'}</div>`;let menu=$('.mention-menu');menu.style.left=Math.min(innerWidth-menu.offsetWidth-10,Math.max(8,r.left))+'px';menu.style.top=Math.max(10,Math.min(r.top-menu.offsetHeight-8,innerHeight-menu.offsetHeight-10))+'px'}
function pickMention(index){let a=ui.mention,c=a?.options[index];if(a?.input&&c){let input=document.getElementById(a.input);input.focus();input.setRangeText('[['+c.ref+']]',a.start,a.end,'end');input.dispatchEvent(new Event('input',{bubbles:true}));closeMenu();return;}let el=editorFor(a?.key||'');if(!c||!el)return;let range=a.range;el.focus();try{range.deleteContents();let wrap=document.createElement('span');wrap.innerHTML=renderRef(c.ref,true);let token=wrap.firstChild,space=document.createTextNode(' ');range.insertNode(space);range.insertNode(token);range.setStartAfter(space);range.collapse(true);let s=window.getSelection();s.removeAllRanges();s.addRange(range)}catch(e){insertRefAtEnd(c.ref,a.key)}saveEditor(el);persist();closeMenu()}
function searchResults(query){let results=allCandidates(ui.space,true).filter(c=>norm(c.title+' '+db.spaces[c.space]?.name).includes(norm(query))).slice(0,35);return results.length?results.map(c=>`<button class="search-item" data-action="search-open" data-ref="${c.ref}">${I(kindIcon[c.type])}<span><span class="kind">${kindName[c.type]}</span><span class="title" style="display:block">${esc(short(c.title,85))}</span><span class="sub" style="display:block">${esc(db.spaces[c.space]?.name)} · ${esc(short(c.sub,65))}</span></span></button>`).join(''):'<div class="empty">Brak wyników w dostępnych projektach.</div>'}
function fitMap(ids=null){if(ui.mapView!=='canvas')return;let canvas=$('#map-canvas');if(!canvas)return;let ns=Object.values(db.nodes).filter(n=>n.map===ui.map&&!n.archived&&(!ids||ids.includes(n.id)));if(!ns.length)return;let minX=Math.min(...ns.map(n=>n.x)),maxX=Math.max(...ns.map(n=>n.x+(innerWidth<1150?200:210))),minY=Math.min(...ns.map(n=>n.y)),maxY=Math.max(...ns.map(n=>n.y+($(`[data-node="${n.id}"]`)?.offsetHeight||110)));let pad=90,z=Math.min(1.2,Math.max(.25,Math.min((canvas.clientWidth-pad*2)/(maxX-minX),(canvas.clientHeight-pad*2)/(maxY-minY))));let c=camera();c.z=z;c.x=(canvas.clientWidth-(maxX-minX)*z)/2-minX*z;c.y=(canvas.clientHeight-(maxY-minY)*z)/2-minY*z;updateWorld()}
function updateWorld(){let w=$('#map-world');if(w){let c=camera();w.style.transform=`translate(${c.x}px,${c.y}px) scale(${c.z})`;let z=$('.zoom-label');if(z)z.textContent=Math.round(c.z*100)+'%'}}
function updateEdgeGeometry(){for(let g of $$('[data-edge]')){let e=db.edges[g.dataset.edge];if(e)$$('path',g).forEach(p=>p.setAttribute('d',edgePath(e)))}}
function zoom(factor,clientX=null,clientY=null){let el=$('#map-canvas');if(!el)return;let r=el.getBoundingClientRect(),c=camera(),x=(clientX??(r.left+r.width/2))-r.left,y=(clientY??(r.top+r.height/2))-r.top,z=Math.min(2.5,Math.max(.2,c.z*factor)),ratio=z/c.z;c.x=x-(x-c.x)*ratio;c.y=y-(y-c.y)*ratio;c.z=z;updateWorld()}
function worldPoint(clientX,clientY){let r=$('#map-canvas').getBoundingClientRect(),c=camera();return {x:(clientX-r.left-c.x)/c.z,y:(clientY-r.top-c.y)/c.z}}
function editNode(id){let n=db.nodes[id];if(!n)return;if(n.reference){openRef(n.reference);toast('To odniesienie. Edytuj materiał u źródła albo dodaj obok własną myśl.');return;}if(ui.mapView==='list'){modal('node-edit',{id});return}ui.selected=[id];render();let node=$(`[data-node="${id}"]`),text=$(`[data-node-text="${id}"]`);if(!text)return;node.classList.add('editing');node.querySelector('.node-actions')?.remove();text.contentEditable='true';text.dataset.original=n.text;text.focus();let r=document.createRange();r.selectNodeContents(text);let s=window.getSelection();s.removeAllRanges();s.addRange(r)}
function finishNodeEdit(el,cancel=false){if(!el||el.contentEditable!=='true')return;let id=el.dataset.nodeText,n=db.nodes[id];el.contentEditable='false';if(!n)return;let value=el.textContent.trim();if(!cancel&&value&&value!==n.text){saveMapUndo();transact('map.node.edit',()=>{n.text=value;db.maps[n.map].version++})}else render()}
function mapLayout(mode){let nodes=Object.values(db.nodes).filter(n=>n.map===ui.map&&!n.archived&&(ui.selected.length<2||ui.selected.includes(n.id)));if(!nodes.length){toast('Najpierw dodaj myśl.');return}saveMapUndo();transact('map.layout',()=>{if(mode==='tree'){let pending=new Set(nodes.map(n=>n.id)),layers=[];while(pending.size){let first=nodes.find(n=>n.root&&pending.has(n.id))||nodes.find(n=>pending.has(n.id)),queue=[[first.id,0]],visited=new Set();let component=[];while(queue.length){let [id,level]=queue.shift();if(!pending.has(id)||visited.has(id))continue;visited.add(id);pending.delete(id);component[level]=component[level]||[];component[level].push(db.nodes[id]);for(let nb of neighbors(id))if(pending.has(nb.id))queue.push([nb.id,level+1]);}layers.push(...component.filter(Boolean));}layers.forEach((row,y)=>row.forEach((n,x)=>{n.x=100+x*290;n.y=70+y*230}));}else nodes.forEach((n,i)=>{n.x=80+(mode==='row'?i:i%3)*290;n.y=110+(mode==='row'?0:Math.floor(i/3))*230});db.maps[ui.map].version++;closeModal()});requestAnimationFrame(()=>fitMap());toast('Zmieniono tylko rozmieszczenie myśli.','map-undo')}
function attachDataURL(file){return new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Nie udało się odczytać pliku.'));r.readAsDataURL(file)})}
function downloadData(name,data,type='text/plain'){let blob=new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
async function copyRef(ref){let url=new URL(location.href);url.hash='space='+encodeURIComponent(ui.space)+'&ref='+encodeURIComponent(ref);try{await navigator.clipboard.writeText(url.toString());toast('Odnośnik skopiowany. Działa z tą samą lokalną bazą danych.')}catch(e){modalShell('Odnośnik do materiału',`<p class="hint">Schowek nie jest dostępny. Skopiuj ręcznie. Odbiorca potrzebuje tej samej bazy danych.</p><textarea readonly rows="3" style="margin-top:12px">${esc(url.toString())}</textarea>`,B('Zamknij','close-modal','','primary'));ui.modal={type:'copy-fallback'}}}
function observeRead(){if(window.fluxReadObserver)window.fluxReadObserver.disconnect();if(!window.IntersectionObserver)return;window.fluxReadObserver=new IntersectionObserver(entries=>{let changed=false;for(let entry of entries)if(entry.isIntersecting&&!document.hidden&&!ui.modal&&ui.drawer?.kind!=='review'&&ui.drawer?.kind!=='agent'){let id=entry.target.dataset.message;if(!prefs().read[id]){prefs().read[id]=true;changed=true;db.notifications.filter(n=>n.user===ui.user&&n.ref==='message:'+id).forEach(n=>n.read=true)}}if(changed)persist()},{threshold:.5});$$('[data-message]').forEach(m=>window.fluxReadObserver.observe(m))}
