function makeFragment(pageId,quote,start){let page=db.pages[pageId],text=pagePlain(page);if(!quote.trim())throw Error('Zaznacz tekst.');let same=Object.values(db.fragments).find(f=>f.page===pageId&&f.version===page.version&&f.quote===quote&&f.prefix===text.slice(Math.max(0,start-40),start));if(same)return same.id;let id=uid('f');transact('wiki.fragment',()=>{db.fragments[id]={id,space:ui.space,page:pageId,quote,version:page.version,prefix:text.slice(Math.max(0,start-40),start),suffix:text.slice(start+quote.length,start+quote.length+40)}},{renderUI:false});return id}
function highlightFragment(f){let status=fragmentStatus(f),root=$('#wiki-content');if(!root||!status.ok){toast('Zachowano cytat, ale nie znaleziono jednoznacznego fragmentu w aktualnej wersji.');return}let walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),n,offset=0,startN,endN,startO,endO;while(n=walker.nextNode()){let next=offset+n.textContent.length;if(!startN&&status.index>=offset&&status.index<next){startN=n;startO=status.index-offset}if(status.index+f.quote.length>offset&&status.index+f.quote.length<=next){endN=n;endO=status.index+f.quote.length-offset;break}offset=next}if(startN&&endN){let range=document.createRange();range.setStart(startN,startO);range.setEnd(endN,endO);let sel=window.getSelection();sel.removeAllRanges();sel.addRange(range);startN.parentElement.scrollIntoView({block:'center',behavior:'instant'});toast('Zaznaczono właściwy fragment.')} }
function downloadDataBytes(a){let binary=atob(a.data.split(',')[1]),bytes=Uint8Array.from(binary,c=>c.charCodeAt(0)),url=URL.createObjectURL(new Blob([bytes],{type:a.type})),link=document.createElement('a');link.href=url;link.download=a.name;link.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function detectTextareaMention(el,force=false){let end=el.selectionStart,match=el.value.slice(0,end).match(/(?:^|\s)@([^\s@]*)$/);if(!match&&!force){if(ui.mention?.input===el.id)closeMenu();return}let q=match?.[1]||'',start=match?end-q.length-1:end,options=allCandidates().filter(c=>norm(c.title+' '+kindName[c.type]).includes(norm(q))).slice(0,9);ui.mention={input:el.id,start,end,options,index:0};renderMention(el)}
